var e=[{slug:"wizytowka-google-dla-przychodni",title:"Wizyt\xF3wka Google dla przychodni",h1:"Wizyt\xF3wka Google dla przychodni: jak j\u0105 ustawi\u0107, \u017Ceby pacjenci trafiali do Ciebie",seoTitle:"Wizyt\xF3wka Google dla przychodni - jak j\u0105 ustawi\u0107 krok po kroku | mediaso",seoDescription:"Profil Firmy w Google dla przychodni i gabinetu: weryfikacja, kategoria g\u0142\xF3wna, us\u0142ugi, godziny, zdj\u0119cia, posty i pytania pacjent\xF3w. Instrukcja krok po kroku.",datePublished:"2026-09-11",dateModified:"2026-09-11",readingMinutes:8,image:{src:"/blog/wizytowka-google-telefon.jpg",alt:"Osoba z kaw\u0105 w d\u0142oni przegl\u0105da wyniki wyszukiwania na smartfonie",width:1600,height:1067,credit:"Wikimedia Commons, CC0",creditUrl:"https://commons.wikimedia.org/wiki/File:Hands-coffee-smartphone-technology_(23698591814).jpg"},lead:'Wizyt\xF3wka Google, czyli Profil Firmy w Google, to wpis przychodni widoczny w mapach i w bloku wynik\xF3w lokalnych nad zwyk\u0142ymi wynikami wyszukiwania. Pacjent, kt\xF3ry wpisuje \u201Eortopeda Pozna\u0144" albo \u201Eprzychodnia Wilda", widzi najpierw trzy plac\xF3wki z mapy, ich oceny, godziny i przycisk \u201EZadzwo\u0144". Wi\u0119kszo\u015B\u0107 z nich dzwoni do jednej z tej tr\xF3jki, nie przewijaj\u0105c dalej. O tym, kt\xF3ra plac\xF3wka trafi do tr\xF3jki, decyduj\u0105 trzy rzeczy: trafno\u015B\u0107 wpisu wzgl\u0119dem zapytania, odleg\u0142o\u015B\u0107 od pacjenta i rozpoznawalno\u015B\u0107 plac\xF3wki, na kt\xF3r\u0105 sk\u0142adaj\u0105 si\u0119 opinie i sp\xF3jne dane w sieci. Na odleg\u0142o\u015B\u0107 nie masz wp\u0142ywu. Na trafno\u015B\u0107 masz wp\u0142yw niemal ca\u0142kowity i to ona jest tematem tego poradnika: od weryfikacji profilu, przez wyb\xF3r kategorii i list\u0119 us\u0142ug, po zdj\u0119cia, posty i pytania pacjent\xF3w. Ca\u0142o\u015B\u0107 da si\u0119 wykona\u0107 samodzielnie w jedno popo\u0142udnie.',sections:[{heading:"Krok 1: przejmij i zweryfikuj profil",paragraphs:["Zanim za\u0142o\u017Cysz nowy profil, wyszukaj swoj\u0105 plac\xF3wk\u0119 w Mapach Google. Przychodnie dzia\u0142aj\u0105ce od kilku lat cz\u0119sto maj\u0105 ju\u017C wpis utworzony automatycznie albo przez by\u0142ego pracownika. Drugi profil pod tym samym adresem to duplikat, kt\xF3ry dzieli opinie i obni\u017Ca widoczno\u015B\u0107 obu wpis\xF3w.",'Je\u015Bli wpis istnieje, kliknij \u201EZarz\u0105dzaj tym profilem" i przejd\u017A weryfikacj\u0119. Google proponuje zwykle nagranie wideo pokazuj\u0105ce szyld, wej\u015Bcie i dokument z adresem, czasem telefon lub list z kodem. Dost\u0119p w\u0142a\u015Bciciela zak\u0142adaj na konto Google plac\xF3wki, nie na prywatn\u0105 skrzynk\u0119 osoby, kt\xF3ra akurat si\u0119 tym zajmuje. Pozosta\u0142ym osobom nadawaj rol\u0119 mened\u017Cera.'],bullets:["sprawd\u017A, czy plac\xF3wka nie ma ju\u017C wpisu lub duplikatu","weryfikacja na koncie firmowym, nie prywatnym","rola w\u0142a\u015Bciciela dla plac\xF3wki, rola mened\u017Cera dla agencji i pracownik\xF3w",'nazwa dok\u0142adnie taka jak na szyldzie, bez dopisk\xF3w w rodzaju \u201Enajlepszy dentysta"'],note:"Dopisywanie fraz do nazwy firmy \u0142amie wytyczne Google. Konkurencja mo\u017Ce to zg\u0142osi\u0107, a skutkiem bywa zawieszenie profilu."},{heading:"Krok 2: kategoria g\u0142\xF3wna decyduje, na co si\u0119 wy\u015Bwietlasz",paragraphs:['Kategoria g\u0142\xF3wna to najwa\u017Cniejsze pole w ca\u0142ym profilu. Google na jej podstawie ocenia, na jakie zapytania plac\xF3wka jest trafn\u0105 odpowiedzi\u0105. Wyb\xF3r \u201EPrzychodnia" jest poprawny, ale og\xF3lny: taki wpis przegra na zapytanie \u201Edermatolog" z gabinetem, kt\xF3ry ma kategori\u0119 \u201EDermatolog".',"Kategori\u0119 g\u0142\xF3wn\u0105 ustaw na us\u0142ug\u0119, kt\xF3ra przynosi plac\xF3wce najwi\u0119cej przychodu albo na kt\xF3rej najbardziej ci zale\u017Cy. Kategorie dodatkowe, do dziewi\u0119ciu, opisuj\u0105 pozosta\u0142e specjalizacje. Nie dodawaj kategorii, kt\xF3rych nie wykonujesz. Obni\u017Caj\u0105 trafno\u015B\u0107 zamiast j\u0105 podnosi\u0107, a pacjent, kt\xF3ry zadzwoni po us\u0142ug\u0119, kt\xF3rej nie ma, jest straconym po\u0142\u0105czeniem dla rejestracji."],bullets:['kategoria g\u0142\xF3wna: najwa\u017Cniejsza us\u0142uga, nie og\xF3lna \u201EPrzychodnia"',"kategorie dodatkowe tylko dla us\u0142ug realnie wykonywanych","raz na kwarta\u0142 sprawd\u017A kategorie trzech konkurent\xF3w z mapy"]},{heading:"Krok 3: us\u0142ugi, opis i atrybuty",paragraphs:['Sekcja us\u0142ug pozwala doda\u0107 ka\u017Cd\u0105 us\u0142ug\u0119 osobno, z kr\xF3tkim opisem i cen\u0105. Pacjent widzi j\u0105 w profilu, a Google czyta j\u0105 przy dopasowaniu zapyta\u0144. Wpisz us\u0142ugi j\u0119zykiem pacjenta: \u201Eusuwanie znamion", nie \u201Edermatochirurgia zmian barwnikowych". Je\u015Bli masz cennik na stronie, ceny w profilu musz\u0105 si\u0119 z nim zgadza\u0107.',"Opis plac\xF3wki ma 750 znak\xF3w. Pierwsze zdania wida\u0107 bez rozwijania, wi\u0119c zacznij od konkret\xF3w: jakie specjalizacje, dla kogo, w jakiej dzielnicy, czy jest NFZ, czy s\u0105 wizyty prywatne. Na ko\u0144cu dopisz atrybuty: dost\u0119p dla w\xF3zk\xF3w, parking, rejestracja online. Pacjent filtruje po nich wyniki cz\u0119\u015Bciej, ni\u017C si\u0119 wydaje."]},{heading:"Krok 4: godziny, telefon i link do rejestracji",paragraphs:["Godziny otwarcia wpisuj tak, jak faktycznie dzia\u0142a rejestracja, nie gabinet zabiegowy. Pacjent, kt\xF3ry dzwoni w godzinach z profilu i nikt nie odbiera, rzadko pr\xF3buje drugi raz. Przed ka\u017Cdym \u015Bwi\u0119tem ustaw godziny specjalne. Google o nie przypomina, a profil bez nich pokazuje w Wigili\u0119 zwyk\u0142y czwartek.","Numer telefonu musi by\u0107 ten sam co na stronie i w innych katalogach, na przyk\u0142ad w ZnanyLekarz. Rozbie\u017Cne numery w sieci os\u0142abiaj\u0105 rozpoznawalno\u015B\u0107 plac\xF3wki. W polu linku do wizyt podaj adres rejestracji online albo podstron\u0119 kontaktu. Link do strony g\u0142\xF3wnej ka\u017Ce pacjentowi szuka\u0107 przycisku jeszcze raz."],bullets:["godziny pracy rejestracji, nie gabinet\xF3w","godziny specjalne przed ka\u017Cdym \u015Bwi\u0119tem i urlopem","jeden numer telefonu wsz\u0119dzie: profil, strona, katalogi","link do umawiania wizyt prowadzi prosto do formularza lub systemu rejestracji"],image:{src:"/blog/wizytowka-google-poczekalnia.jpg",alt:"Rejestracja i poczekalnia przychodni z krzes\u0142ami dla pacjent\xF3w",width:1600,height:1068,credit:"USDA, domena publiczna",creditUrl:"https://commons.wikimedia.org/wiki/File:RD_CFDL-Lytle_Community_Health_Center_-_Community_Facility_Direct_Loan_(20171205-RD-LSC-0238).jpg"}},{heading:"Krok 5: zdj\u0119cia, kt\xF3re odpowiadaj\u0105 na pytania pacjenta",paragraphs:["Pacjent przed pierwsz\u0105 wizyt\u0105 chce wiedzie\u0107 trzy rzeczy: jak wygl\u0105da wej\u015Bcie, jak wygl\u0105da poczekalnia i kto go przyjmie. Na te pytania odpowiadaj\u0105 zdj\u0119cia. Wej\u015Bcie od ulicy, najlepiej z szyldem i numerem budynku, oszcz\u0119dza kr\u0105\u017Cenia wok\xF3\u0142 kamienicy. Poczekalnia i gabinet pokazuj\u0105 standard. Zdj\u0119cia zespo\u0142u buduj\u0105 zaufanie szybciej ni\u017C opis.","R\xF3b zdj\u0119cia w dzie\u0144, bez pacjent\xF3w w kadrze. Twarz osoby w poczekalni przychodni to informacja o jej zdrowiu, a na jej publikacj\u0119 potrzebna jest pisemna zgoda. Wgrywaj nowe zdj\u0119cia co kilka miesi\u0119cy. Profil z pi\u0119cioma zdj\u0119ciami sprzed czterech lat wygl\u0105da na porzucony, nawet je\u015Bli plac\xF3wka pracuje pe\u0142n\u0105 par\u0105."],bullets:["wej\u015Bcie od ulicy z widocznym szyldem i numerem","poczekalnia, rejestracja i przynajmniej jeden gabinet","zesp\xF3\u0142: lekarze i rejestracja, za zgod\u0105 os\xF3b na zdj\u0119ciach","logo i zdj\u0119cie w tle ustawione r\u0119cznie, nie wybrane przez Google","bez pacjent\xF3w w kadrze"],image:{src:"/blog/wizytowka-google-wejscie.jpg",alt:"Wej\u015Bcie do budynku kliniki od strony ulicy z widocznym zadaszeniem",width:1600,height:1067,credit:"Wikimedia Commons, CC0",creditUrl:"https://commons.wikimedia.org/wiki/File:Clinic_entrance,_Brown_Building,_McGill_University,_Oct_29_2022.jpg"}},{heading:"Krok 6: posty oraz pytania i odpowiedzi",paragraphs:["Posty w profilu to kr\xF3tkie komunikaty ze zdj\u0119ciem: nowy specjalista, zmiana godzin, szczepienia sezonowe, dost\u0119pne terminy. Pojedynczy post nie przesunie plac\xF3wki w wynikach, ale regularne publikowanie pokazuje pacjentowi i Google, \u017Ce profil kto\u015B prowadzi. Wystarczy jeden post na dwa tygodnie. Tre\u015B\u0107 podlega tym samym ograniczeniom co reklama \u015Bwiadcze\u0144 zdrowotnych: informujesz, nie zach\u0119casz i nie obiecujesz efektu.","Sekcj\u0119 pyta\u0144 i odpowiedzi mo\u017Ce wype\u0142ni\u0107 ka\u017Cdy u\u017Cytkownik Google, tak\u017Ce w imieniu plac\xF3wki. Zajrzyj tam i odpowiedz na pytania, kt\xF3re ju\u017C wisz\u0105. Potem dodaj z konta plac\xF3wki pi\u0119\u0107 pyta\u0144, kt\xF3re rejestracja s\u0142yszy codziennie: czy jest NFZ, czy potrzebne jest skierowanie, gdzie zaparkowa\u0107, ile trwa pierwsza wizyta, czy przyjmujecie dzieci. Ka\u017Cda odpowied\u017A to jeden telefon mniej do rejestracji."]},{heading:"Krok 7: sprawdzaj statystyki raz w miesi\u0105cu",paragraphs:["Panel Profilu Firmy pokazuje liczb\u0119 po\u0142\u0105cze\u0144, klikni\u0119\u0107 w tras\u0119 i wej\u015B\u0107 na stron\u0119 oraz zapytania, na kt\xF3re profil si\u0119 wy\u015Bwietli\u0142. Zapisuj te liczby co miesi\u0105c w prostej tabeli. Po trzech miesi\u0105cach zobaczysz, czy zmiany kategorii, us\u0142ug i zdj\u0119\u0107 prze\u0142o\u017Cy\u0142y si\u0119 na telefony.","Je\u015Bli po\u0142\u0105cze\u0144 jest du\u017Co, a nowych pacjent\xF3w nie przybywa, problem le\u017Cy zwykle poza profilem: w nieodebranych telefonach albo w braku wolnych termin\xF3w. Wizyt\xF3wka \u015Bci\u0105ga pacjenta do s\u0142uchawki, dalej przejmuje rejestracja."]}],faq:[{question:"Czy wizyt\xF3wka Google dla przychodni jest p\u0142atna?",answer:"Nie. Profil Firmy w Google jest bezp\u0142atny, a jego za\u0142o\u017Cenie, weryfikacja i prowadzenie nie wymagaj\u0105 \u017Cadnych op\u0142at. P\u0142atne s\u0105 jedynie reklamy Google Ads, kt\xF3re mog\u0105 wy\u015Bwietla\u0107 si\u0119 obok wynik\xF3w lokalnych, ale nie s\u0105 potrzebne, \u017Ceby profil dzia\u0142a\u0142."},{question:"Jak\u0105 kategori\u0119 wybra\u0107 dla przychodni wielospecjalistycznej?",answer:'Jako kategori\u0119 g\u0142\xF3wn\u0105 wybierz specjalizacj\u0119, na kt\xF3rej plac\xF3wce najbardziej zale\u017Cy lub kt\xF3ra przynosi najwi\u0119cej przychodu. Pozosta\u0142e specjalizacje dodaj jako kategorie dodatkowe, maksymalnie dziewi\u0119\u0107. Og\xF3lna kategoria \u201EPrzychodnia" sprawdza si\u0119 jako dodatkowa, rzadko jako g\u0142\xF3wna.'},{question:"Czy ka\u017Cdy lekarz w przychodni mo\u017Ce mie\u0107 w\u0142asn\u0105 wizyt\xF3wk\u0119?",answer:"Wytyczne Google dopuszczaj\u0105 osobne profile lekarzy przyjmuj\u0105cych w plac\xF3wce, je\u015Bli przyjmuj\u0105 pacjent\xF3w pod tym adresem. W ma\u0142ej przychodni zwykle lepiej skupi\u0107 opinie i zdj\u0119cia na jednym profilu plac\xF3wki. Osobne profile lekarzy maj\u0105 sens przy znanych specjalistach, kt\xF3rych pacjenci szukaj\u0105 po nazwisku."},{question:"Jak d\u0142ugo trwa weryfikacja profilu w Google?",answer:"Weryfikacja wideo lub telefoniczna trwa zwykle od kilku godzin do kilku dni roboczych. List z kodem dociera w ci\u0105gu oko\u0142o dw\xF3ch tygodni. Zmiany w ju\u017C zweryfikowanym profilu, na przyk\u0142ad kategorii czy godzin, pojawiaj\u0105 si\u0119 w wynikach zazwyczaj w ci\u0105gu kilku dni."},{question:"Po jakim czasie wizyt\xF3wka zacznie przynosi\u0107 telefony?",answer:"Poprawki kategorii, us\u0142ug i godzin zaczynaj\u0105 dzia\u0142a\u0107 zwykle po dw\xF3ch do sze\u015Bciu tygodni. Efekt zale\u017Cy od odleg\u0142o\u015Bci pacjent\xF3w, liczby i \u015Bwie\u017Co\u015Bci opinii oraz od tego, jak dopracowane s\u0105 profile konkurencyjnych plac\xF3wek w okolicy."}],related:[{path:"/uslugi/wizytowka-google-dla-placowki",label:"Wizyt\xF3wka Google dla plac\xF3wki",description:"Poprowadzimy profil za Ciebie, z raportem widoczno\u015Bci w mapach co miesi\u0105c."},{path:"/wiedza/jak-zbierac-opinie-pacjentow",label:"Jak zbiera\u0107 opinie pacjent\xF3w zgodnie z prawem",description:"Opinie to drugi po trafno\u015Bci czynnik, kt\xF3ry decyduje o pozycji w mapach."},{path:"/wiedza/pozycjonowanie-kliniki-krok-po-kroku",label:"Pozycjonowanie kliniki krok po kroku",description:"Wizyt\xF3wka jako jeden z sze\u015Bciu etap\xF3w widoczno\u015Bci w Google."}]},{slug:"czym-jest-marketing-medyczny",title:"Czym jest marketing medyczny",h1:"Czym jest marketing medyczny i czym r\xF3\u017Cni si\u0119 od zwyk\u0142ego marketingu",seoTitle:"Czym jest marketing medyczny - definicja i zasady | mediaso",seoDescription:"Marketing medyczny to informowanie o us\u0142ugach plac\xF3wki w granicach przepis\xF3w o reklamie \u015Bwiadcze\u0144 zdrowotnych. Wyja\u015Bniamy zakres, ograniczenia i kana\u0142y.",datePublished:"2026-08-29",dateModified:"2026-08-29",readingMinutes:7,lead:"Marketing medyczny to ca\u0142o\u015B\u0107 dzia\u0142a\u0144, kt\xF3rymi plac\xF3wka zdrowotna informuje pacjent\xF3w o swoich us\u0142ugach, dost\u0119pno\u015Bci i kompetencjach zespo\u0142u, prowadzonych w granicach przepis\xF3w ograniczaj\u0105cych reklam\u0119 \u015Bwiadcze\u0144 zdrowotnych. Od marketingu w innych bran\u017Cach r\xF3\u017Cni go przede wszystkim to, czego nie wolno: nie mo\u017Cna obiecywa\u0107 efektu leczenia, zach\u0119ca\u0107 do korzystania ze \u015Bwiadcze\u0144 w spos\xF3b nachalny, wykorzystywa\u0107 wizerunku pacjenta bez pisemnej zgody ani budowa\u0107 przekazu na por\xF3wnaniach z konkretnymi plac\xF3wkami. Zostaje bardzo du\u017Co miejsca na komunikacj\u0119 opart\u0105 na faktach: zakres us\u0142ug, ceny, terminy, kwalifikacje specjalist\xF3w, przebieg wizyty, przygotowanie do bada\u0144. Praktyka pokazuje, \u017Ce to w\u0142a\u015Bnie ta rzeczowa warstwa przynosi plac\xF3wkom najwi\u0119cej kontakt\xF3w, bo odpowiada na pytania, kt\xF3re pacjent zadaje przed telefonem.",sections:[{heading:"Co mie\u015Bci si\u0119 w marketingu medycznym",paragraphs:['Zakres jest szerszy, ni\u017C sugeruje s\u0142owo \u201Ereklama". Obejmuje stron\u0119 internetow\u0105 plac\xF3wki i jej widoczno\u015B\u0107 w wyszukiwarce, Profil Firmy w Google z opiniami pacjent\xF3w, profile w mediach spo\u0142eczno\u015Bciowych, materia\u0142y drukowane w poczekalni, komunikacj\u0119 SMS i e-mail z pacjentami oraz spos\xF3b, w jaki rejestracja odbiera telefon.',"Ostatni punkt bywa pomijany, a to on rozstrzyga wynik. Kampania, kt\xF3ra generuje telefony w godzinach, gdy nikt ich nie odbiera, jest wydatkiem bez efektu. Dlatego marketing plac\xF3wki zaczyna si\u0119 od sprawdzenia, co si\u0119 dzieje z pacjentem, kt\xF3ry ju\u017C pr\xF3buje si\u0119 skontaktowa\u0107."],bullets:["strona internetowa z podstronami us\u0142ug i cennikiem","widoczno\u015B\u0107 w wyszukiwarce na zapytania lokalne i us\u0142ugowe","Profil Firmy w Google: kategorie, godziny, zdj\u0119cia, opinie","media spo\u0142eczno\u015Bciowe i obs\u0142uga wiadomo\u015Bci od pacjent\xF3w","komunikacja z pacjentami: potwierdzenia, przypomnienia, zaproszenia na kontrole","obs\u0142uga telefonu w rejestracji jako ostatni etap \u015Bcie\u017Cki"]},{heading:"Granice prawne w skr\xF3cie",paragraphs:["Reklama dzia\u0142alno\u015Bci leczniczej jest w Polsce ograniczona. Podmiot leczniczy mo\u017Ce podawa\u0107 do wiadomo\u015Bci publicznej informacje o zakresie i rodzajach udzielanych \u015Bwiadcze\u0144, ale forma i tre\u015B\u0107 tych informacji nie mo\u017Ce mie\u0107 cech zach\u0119ty do korzystania ze \u015Bwiadcze\u0144. Lekarzy dodatkowo wi\u0105\u017Ce kodeks etyki lekarskiej, a apteki i wyroby medyczne maj\u0105 w\u0142asne, ostrzejsze re\u017Cimy.","W praktyce dzieli to komunikaty na dwie grupy. Bezpieczne: opis us\u0142ugi, cena, czas trwania, przygotowanie, kwalifikacje lekarza, dost\u0119pne terminy, wyposa\u017Cenie. Ryzykowne: obietnice wyniku, przekaz oparty na strachu, promocje w stylu handlowym, por\xF3wnania z konkurencj\u0105 po nazwie, przed i po bez zgody i kontekstu."],note:"To skr\xF3t, nie opinia prawna. Przy us\u0142ugach z pogranicza - medycyna estetyczna, stomatologia komercyjna - warto skonsultowa\u0107 materia\u0142y z prawnikiem bran\u017Cowym."},{heading:"Sk\u0105d realnie przychodz\u0105 pacjenci",paragraphs:["W wi\u0119kszo\u015Bci plac\xF3wek, kt\xF3rym pomagamy, najsilniejszym kana\u0142em jest wyszukiwarka razem z mapami. Pacjent szuka konkretnej us\u0142ugi w konkretnej okolicy, sprawdza opinie i dzwoni do jednej z trzech pierwszych plac\xF3wek na li\u015Bcie. Drugim kana\u0142em jest polecenie - i tu te\u017C ko\u0144czy si\u0119 w Google, bo pacjent weryfikuje polecan\u0105 plac\xF3wk\u0119, zanim zadzwoni.","Media spo\u0142eczno\u015Bciowe rzadko generuj\u0105 pierwszy kontakt, ale pracuj\u0105 na decyzj\u0119: pacjent sprawdza profil i szuka \u015Bladu, \u017Ce plac\xF3wka dzia\u0142a. Reklama p\u0142atna dzia\u0142a wtedy, gdy jest po co dzwoni\u0107 - s\u0105 wolne terminy i kto\u015B odbiera telefon."]},{heading:"Od czego zacz\u0105\u0107 w ma\u0142ej plac\xF3wce",paragraphs:["Kolejno\u015B\u0107, kt\xF3ra daje najwi\u0119cej przy najmniejszym bud\u017Cecie, jest za ka\u017Cdym razem podobna. Najpierw wizyt\xF3wka Google: w\u0142a\u015Bciwa kategoria, komplet godzin, zdj\u0119cia, opisy us\u0142ug. Potem opinie - systemowa pro\u015Bba po wizycie, kierowana do wszystkich pacjent\xF3w. Potem strona z podstronami us\u0142ug i cennikiem.","Reklama p\u0142atna jest ostatnia, nie pierwsza. Uruchomiona przed uporz\u0105dkowaniem tych trzech rzeczy podnosi koszt pozyskania pacjenta i maskuje problem, zamiast go rozwi\u0105za\u0107."],bullets:["wizyt\xF3wka Google z poprawn\u0105 kategori\u0105 g\u0142\xF3wn\u0105","proces zbierania opinii po wizycie","podstrona dla ka\u017Cdej us\u0142ugi, kt\xF3r\u0105 plac\xF3wka sprzedaje","pomiar nieodebranych po\u0142\u0105cze\u0144 w rejestracji","dopiero potem kampanie p\u0142atne"]},{heading:"Jak mierzy\u0107, czy to dzia\u0142a",paragraphs:["Zasi\u0119gi i polubienia nie s\u0105 wynikiem. Liczby, kt\xF3re maj\u0105 znaczenie dla w\u0142a\u015Bciciela plac\xF3wki, to liczba po\u0142\u0105cze\u0144 i formularzy, odsetek po\u0142\u0105cze\u0144 odebranych, liczba um\xF3wionych wizyt oraz udzia\u0142 pacjent\xF3w pierwszorazowych.","Minimalny zestaw narz\u0119dzi jest darmowy: Google Search Console pokazuje zapytania i wej\u015Bcia z wyszukiwarki, statystyki Profilu Firmy pokazuj\u0105 telefony i klikni\u0119cia w tras\u0119, a raport z centrali telefonicznej pokazuje, ile z tych telefon\xF3w zosta\u0142o odebranych. Trzy \u017Ar\xF3d\u0142a wystarcz\u0105, \u017Ceby przesta\u0107 zgadywa\u0107."]}],faq:[{question:"Czy plac\xF3wka medyczna mo\u017Ce si\u0119 reklamowa\u0107 w Polsce?",answer:"Mo\u017Ce informowa\u0107 o zakresie i rodzajach udzielanych \u015Bwiadcze\u0144, cenach, dost\u0119pno\u015Bci i kwalifikacjach zespo\u0142u. Ograniczenia dotycz\u0105 formy: przekaz nie mo\u017Ce mie\u0107 cech zach\u0119ty do korzystania ze \u015Bwiadcze\u0144 ani obiecywa\u0107 efektu leczenia. Rzetelna informacja o us\u0142udze jest dozwolona i to na niej opiera si\u0119 skuteczna komunikacja plac\xF3wek."},{question:"Ile kosztuje marketing medyczny w ma\u0142ej przychodni?",answer:"Pierwsze kroki - uporz\u0105dkowanie wizyt\xF3wki Google i proces zbierania opinii - kosztuj\u0105 prac\u0119, nie bud\u017Cet mediowy. Sta\u0142a obs\u0142uga social medi\xF3w zaczyna si\u0119 w okolicach 2 000-2 500 z\u0142otych netto miesi\u0119cznie, strona internetowa od kilku tysi\u0119cy z\u0142otych jednorazowo, a bud\u017Cet reklamowy zale\u017Cy od tego, ile wolnych termin\xF3w plac\xF3wka ma do zape\u0142nienia."},{question:"Czy marketing medyczny to to samo co SEO?",answer:"Nie. SEO jest jego cz\u0119\u015Bci\u0105 i odpowiada za widoczno\u015B\u0107 w wynikach wyszukiwania. Marketing medyczny obejmuje te\u017C wizyt\xF3wk\u0119 Google, social media, komunikacj\u0119 z pacjentami i obs\u0142ug\u0119 zg\u0142osze\u0144 w rejestracji."}],related:[{path:"/uslugi/pozycjonowanie-klinik",label:"Pozycjonowanie klinik",description:"Najmocniejszy kana\u0142 pozyskiwania pacjent\xF3w rozbity na etapy."},{path:"/wiedza/rodo-w-marketingu-placowki-medycznej",label:"RODO w marketingu plac\xF3wki medycznej",description:"Zgody, wizerunek i dane pacjent\xF3w w materia\u0142ach marketingowych."},{path:"/diagnostyka",label:"Diagnostyka wzrostu plac\xF3wki",description:"Sprawd\u017A w 20 pytaniach, kt\xF3ry etap \u015Bcie\u017Cki pacjenta si\u0119 urywa."}]},{slug:"pozycjonowanie-kliniki-krok-po-kroku",title:"Pozycjonowanie kliniki krok po kroku",h1:"Pozycjonowanie kliniki krok po kroku",seoTitle:"Pozycjonowanie kliniki krok po kroku - poradnik | mediaso",seoDescription:"Kolejno\u015B\u0107 dzia\u0142a\u0144 SEO dla kliniki: audyt, frazy lokalne, podstrony us\u0142ug, wizyt\xF3wka Google, tre\u015Bci i pomiar. Konkretne kroki do wykonania samodzielnie.",datePublished:"2026-08-29",dateModified:"2026-08-29",readingMinutes:9,lead:"Pozycjonowanie kliniki daje si\u0119 roz\u0142o\u017Cy\u0107 na sze\u015B\u0107 krok\xF3w wykonywanych po kolei, a nie r\xF3wnolegle. Najpierw ustalasz, na jakie zapytania pacjenci realnie szukaj\u0105 twoich us\u0142ug w twoim mie\u015Bcie. Potem sprawdzasz, czy strona w og\xF3le jest indeksowana i jak d\u0142ugo si\u0119 \u0142aduje na telefonie. Trzeci krok to rozbicie oferty na osobne podstrony - jedna us\u0142uga, jeden adres. Czwarty to wizyt\xF3wka Google, kt\xF3ra w medycynie odpowiada za wi\u0119kszo\u015B\u0107 ruchu lokalnego. Pi\u0105ty to tre\u015B\u0107 odpowiadaj\u0105ca na pytania zadawane przed wizyt\u0105. Sz\xF3sty to pomiar: pozycje, wej\u015Bcia i telefony. Ta kolejno\u015B\u0107 ma znaczenie, bo ka\u017Cdy krok korzysta z poprzedniego. Publikowanie tre\u015Bci na stronie, kt\xF3rej Google nie indeksuje, jest prac\u0105 wyrzucon\u0105 w b\u0142oto.",sections:[{heading:"Krok 1: lista fraz z podzia\u0142em na intencje",paragraphs:["Zacznij od Google Search Console. W raporcie skuteczno\u015Bci zobaczysz, na jakie zapytania strona ju\u017C si\u0119 wy\u015Bwietla i na kt\xF3rych pozycjach. Frazy z pozycji 8-20 to najta\u0144szy wzrost, jaki masz do wzi\u0119cia - Google ju\u017C uznaje stron\u0119 za sensown\u0105 odpowied\u017A, brakuje niewiele.","Do tego dopisz zapytania, kt\xF3rych pacjenci u\u017Cywaj\u0105, a kt\xF3rych na li\u015Bcie nie ma. Najpro\u015Bciej zebra\u0107 je od rejestracji: to zestaw pyta\u0144 padaj\u0105cych codziennie przez telefon. Podziel ca\u0142o\u015B\u0107 na trzy grupy: zapytania us\u0142ugowe z miastem, zapytania o cen\u0119 i zapytania informacyjne o przebiegu zabiegu."]},{heading:"Krok 2: sprawd\u017A, czy Google widzi twoj\u0105 stron\u0119",paragraphs:['Wpisz w wyszukiwark\u0119 \u201Esite:" i adres swojej domeny. Je\u017Celi wynik pokazuje mniej stron, ni\u017C ich naprawd\u0119 masz, cz\u0119\u015B\u0107 serwisu nie jest zaindeksowana. W Search Console znajdziesz pow\xF3d w raporcie indeksowania.',"Drugi test: otw\xF3rz stron\u0119 na telefonie w zasi\u0119gu 4G i policz, ile sekund mija do pojawienia si\u0119 tre\u015Bci. Powy\u017Cej trzech sekund tracisz pacjent\xF3w jeszcze przed wej\u015Bciem. Trzeci test: wy\u0142\u0105cz JavaScript w przegl\u0105darce. Je\u017Celi strona jest pusta, wyszukiwarka ma z ni\u0105 k\u0142opot podobny do twojego."],bullets:['sprawd\u017A liczb\u0119 zaindeksowanych podstron zapytaniem \u201Esite:"',"przejrzyj raport indeksowania w Google Search Console","zmierz czas \u0142adowania na telefonie, nie na komputerze w biurze","sprawd\u017A, czy ka\u017Cda podstrona ma w\u0142asny tytu\u0142 i opis"]},{heading:"Krok 3: jedna us\u0142uga, jeden adres",paragraphs:['To jest zmiana o najwi\u0119kszym wp\u0142ywie i jednocze\u015Bnie ta, kt\xF3r\u0105 plac\xF3wki odk\u0142adaj\u0105 najd\u0142u\u017Cej. Strona \u201ENasze us\u0142ugi" z list\u0105 dwudziestu punkt\xF3w nie zarankuje na \u017Cadn\u0105 z nich. Google przypisuje wynik do adresu, wi\u0119c ka\u017Cda us\u0142uga potrzebuje w\u0142asnego.',"Zacznij od trzech us\u0142ug o najwi\u0119kszej warto\u015Bci. Ka\u017Cda dostaje: opis przebiegu wizyty, czas trwania, cen\u0119 lub przedzia\u0142 cenowy, przygotowanie pacjenta, przeciwwskazania, informacj\u0119 o tym, kto j\u0105 wykonuje, i sekcj\u0119 z pytaniami. To zwykle 600-1000 s\u0142\xF3w napisanych konkretnie, bez wst\u0119p\xF3w o trosce o zdrowie."]},{heading:"Krok 4: wizyt\xF3wka Google",paragraphs:['W medycynie mapy odpowiadaj\u0105 za wi\u0119kszo\u015B\u0107 kontakt\xF3w lokalnych. Ustaw kategori\u0119 g\u0142\xF3wn\u0105 na t\u0119 us\u0142ug\u0119, na kt\xF3rej najbardziej ci zale\u017Cy - kategoria \u201Eprzychodnia" nie wy\u015Bwietli ci\u0119 na zapytanie o konkretnego specjalist\u0119. Uzupe\u0142nij kategorie dodatkowe, list\u0119 us\u0142ug, godziny \u0142\u0105cznie ze \u015Bwi\u0119tami, zdj\u0119cia wej\u015Bcia od ulicy i wn\u0119trz.',"Potem opinie. Popro\u015B o nie wszystkich pacjent\xF3w z danej grupy, nie tylko zadowolonych, i nie oferuj niczego w zamian. Odpowiadaj na ka\u017Cd\u0105, tak\u017Ce negatywn\u0105, nie potwierdzaj\u0105c publicznie, \u017Ce autor by\u0142 pacjentem - to informacja o jego zdrowiu."]},{heading:"Krok 5: tre\u015B\u0107, kt\xF3ra odpowiada na pytania",paragraphs:["Artyku\u0142y w bazie wiedzy pracuj\u0105 na zapytania zadawane przed decyzj\u0105: ile trwa leczenie, jak si\u0119 przygotowa\u0107, co obejmuje cena, kiedy zg\u0142osi\u0107 si\u0119 pilnie. Napisz je j\u0119zykiem pacjenta, nie j\u0119zykiem opisu procedury z podr\u0119cznika.","Ka\u017Cdy tekst medyczny powinien przej\u015B\u0107 przez lekarza z plac\xF3wki. To nie tylko kwestia bezpiecze\u0144stwa - autorstwo i nadz\xF3r merytoryczny s\u0105 sygna\u0142em jako\u015Bci dla wyszukiwarki, kt\xF3ra przy tematach zdrowotnych ocenia wiarygodno\u015B\u0107 \u017Ar\xF3d\u0142a ostrzej ni\u017C gdzie indziej."],bullets:["artyku\u0142 na ka\u017Cde powtarzalne pytanie z rejestracji","podpis autora i osoby, kt\xF3ra sprawdzi\u0142a tre\u015B\u0107 merytorycznie","link z artyku\u0142u do podstrony us\u0142ugi, kt\xF3rej dotyczy","aktualizacja daty przy realnej zmianie tre\u015Bci, nie co miesi\u0105c"]},{heading:"Krok 6: pomiar",paragraphs:["Raz w miesi\u0105cu zapisuj cztery liczby: pozycje na uzgodnionej li\u015Bcie fraz, wej\u015Bcia z wyszukiwarki, telefony i klikni\u0119cia w tras\u0119 z wizyt\xF3wki oraz liczb\u0119 nowych pacjent\xF3w. Bez tego nie odr\xF3\u017Cnisz efektu sezonu od efektu pracy.","Pierwszych ruch\xF3w spodziewaj si\u0119 po 6-10 tygodniach na frazach lokalnych. Frazy og\xF3lne w du\u017Cym mie\u015Bcie wymagaj\u0105 kwarta\u0142\xF3w. Je\u017Celi po p\xF3\u0142 roku systematycznej pracy nic si\u0119 nie rusza, problem le\u017Cy zwykle w tym, \u017Ce konkurencja ma dziesi\u0105tki podstron, a ty trzy."]}],faq:[{question:"Ile kosztuje pozycjonowanie kliniki?",answer:"Sta\u0142a obs\u0142uga SEO dla plac\xF3wki lokalnej to zwykle wydatek rz\u0119du kilku tysi\u0119cy z\u0142otych netto miesi\u0119cznie, zale\u017Cnie od liczby us\u0142ug i konkurencji w mie\u015Bcie. Cz\u0119\u015B\u0107 pracy - wizyt\xF3wka Google, opinie, uzupe\u0142nienie tre\u015Bci - da si\u0119 wykona\u0107 w\u0142asnymi si\u0142ami i to od niej warto zacz\u0105\u0107."},{question:"Czy da si\u0119 pozycjonowa\u0107 klinik\u0119 samodzielnie?",answer:"Kroki 1, 2 i 4 z tego poradnika wykonuje si\u0119 bez wiedzy technicznej i one daj\u0105 najwi\u0119cej na start. Rozbicie oferty na podstrony i praca nad tre\u015Bci\u0105 wymagaj\u0105 wi\u0119cej czasu ni\u017C umiej\u0119tno\u015Bci. Zewn\u0119trzne wsparcie zwykle przyspiesza, ale nie jest warunkiem pierwszych efekt\xF3w."},{question:"Jak d\u0142ugo czeka si\u0119 na efekty SEO w bran\u017Cy medycznej?",answer:"Frazy lokalne o niskiej konkurencji ruszaj\u0105 zwykle po 6-10 tygodniach od wdro\u017Cenia zmian. Zapytania og\xF3lne w du\u017Cych miastach zajmuj\u0105 od dw\xF3ch do czterech kwarta\u0142\xF3w. Tempo zale\u017Cy g\u0142\xF3wnie od tego, ile podstron ma konkurencja i od jak dawna publikuje."}],related:[{path:"/uslugi/pozycjonowanie-klinik",label:"Pozycjonowanie klinik",description:"Ten sam proces prowadzony przez nas, z raportowaniem co miesi\u0105c."},{path:"/uslugi/wizytowka-google-dla-placowki",label:"Wizyt\xF3wka Google dla plac\xF3wki",description:"Krok czwarty rozpisany na szczeg\xF3\u0142y."},{path:"/wiedza/ile-kosztuje-strona-dla-przychodni",label:"Ile kosztuje strona internetowa dla przychodni",description:"Z czego sk\u0142ada si\u0119 wycena i co realnie wp\u0142ywa na cen\u0119."}]},{slug:"rodo-w-marketingu-placowki-medycznej",title:"RODO w marketingu plac\xF3wki medycznej",h1:"RODO w marketingu plac\xF3wki medycznej",seoTitle:"RODO w marketingu plac\xF3wki medycznej | mediaso",seoDescription:"Zgody na wizerunek, opinie pacjent\xF3w, SMS-y marketingowe, umowy powierzenia z agencj\u0105 i piksele reklamowe. Co plac\xF3wka musi mie\u0107 na pi\u015Bmie.",datePublished:"2026-08-29",dateModified:"2026-08-29",readingMinutes:8,lead:"W plac\xF3wce medycznej niemal ka\u017Cdy materia\u0142 marketingowy dotyka danych szczeg\xF3lnej kategorii, bo sam fakt korzystania ze \u015Bwiadcze\u0144 zdrowotnych jest informacj\u0105 o zdrowiu. Dlatego zdj\u0119cie pacjenta w poczekalni, publiczna odpowied\u017A na opini\u0119 potwierdzaj\u0105ca, \u017Ce kto\u015B by\u0142 u was na wizycie, czy SMS z zaproszeniem na badanie kontrolne wymagaj\u0105 innej ostro\u017Cno\u015Bci ni\u017C analogiczne dzia\u0142ania w restauracji. Regu\u0142a praktyczna brzmi: nie publikuj i nie wysy\u0142aj niczego, co pozwala powi\u0105za\u0107 konkretn\u0105 osob\u0119 z korzystaniem z twoich us\u0142ug, dop\xF3ki nie masz na to zgody na pi\u015Bmie. Druga regu\u0142a dotyczy dostawc\xF3w: agencja, infolinia i firma wysy\u0142aj\u0105ca SMS-y przetwarzaj\u0105 dane w twoim imieniu, wi\u0119c potrzebujesz z nimi umowy powierzenia przetwarzania.",sections:[{heading:"Zgoda na wizerunek: co musi w niej by\u0107",paragraphs:["Zgoda ustna nie wystarczy, bo w razie sporu nie da si\u0119 jej wykaza\u0107. Dokument powinien wskazywa\u0107, kto publikuje, jakie materia\u0142y, w jakich kana\u0142ach i przez jaki czas, oraz zawiera\u0107 informacj\u0119 o prawie wycofania zgody w dowolnym momencie.","Osobno traktuj zdj\u0119cia przed i po. Pokazuj\u0105 one nie tylko wizerunek, ale te\u017C przebieg leczenia, wi\u0119c zgoda musi to obejmowa\u0107 wprost. Wycofanie zgody oznacza usuni\u0119cie materia\u0142u ze wszystkich kana\u0142\xF3w, w kt\xF3rych go opublikowano - dlatego warto prowadzi\u0107 rejestr publikacji."],bullets:["forma pisemna albo dokumentowa, z mo\u017Cliwo\u015Bci\u0105 odtworzenia tre\u015Bci zgody","wskazanie kana\u0142\xF3w: strona, Facebook, Instagram, materia\u0142y drukowane","okres publikacji i zasady wycofania zgody","osobna zgoda na zdj\u0119cia dokumentuj\u0105ce przebieg leczenia","rejestr, gdzie i kiedy materia\u0142 zosta\u0142 opublikowany"]},{heading:"Opinie pacjent\xF3w",paragraphs:["Pro\u015Bba o opini\u0119 wys\u0142ana pacjentowi po wizycie to komunikacja zwi\u0105zana z wykonan\u0105 us\u0142ug\u0105, ale spos\xF3b jej wys\u0142ania ma znaczenie: SMS z linkiem do wystawienia opinii bywa kwalifikowany jako informacja handlowa, wi\u0119c bezpieczniej jest opiera\u0107 go na zgodzie zebranej przy rejestracji.","Odpowiadaj\u0105c publicznie na opini\u0119, nigdy nie potwierdzaj, \u017Ce autor by\u0142 twoim pacjentem, nie odno\u015B si\u0119 do przebiegu leczenia i nie prostuj fakt\xF3w medycznych w komentarzu. Standardowa odpowied\u017A to podzi\u0119kowanie i zaproszenie do kontaktu bezpo\u015Bredniego. Wyja\u015Bnienia prowadzi si\u0119 poza publiczn\u0105 cz\u0119\u015Bci\u0105."]},{heading:"Umowa powierzenia z agencj\u0105 i dostawcami",paragraphs:["Je\u017Celi agencja obs\u0142uguje wiadomo\u015Bci od pacjent\xF3w, prowadzi wysy\u0142k\u0119 SMS albo ma dost\u0119p do systemu rejestracji, przetwarza dane w imieniu plac\xF3wki. Wymaga to umowy powierzenia okre\u015Blaj\u0105cej zakres, cel, kategorie danych, obowi\u0105zki bezpiecze\u0144stwa i zasady usuni\u0119cia danych po zako\u0144czeniu wsp\xF3\u0142pracy.","To samo dotyczy dostawcy hostingu, systemu do wysy\u0142ki SMS i firmy prowadz\u0105cej infolini\u0119. W praktyce warto prowadzi\u0107 prost\u0105 list\u0119 wszystkich podmiot\xF3w maj\u0105cych dost\u0119p do danych - przy kontroli jest to pierwszy dokument, o kt\xF3ry pyta inspektor."]},{heading:"Formularze i piksele reklamowe",paragraphs:['Formularz kontaktowy powinien zbiera\u0107 wy\u0142\u0105cznie dane potrzebne do odpowiedzi i zawiera\u0107 klauzul\u0119 informacyjn\u0105: kto jest administratorem, w jakim celu przetwarza dane, jak d\u0142ugo je trzyma i jakie prawa ma osoba, kt\xF3ra je zostawia. Pole \u201Eopisz sw\xF3j problem zdrowotny" lepiej z formularza usun\u0105\u0107 - zbiera dane o zdrowiu bez potrzeby.',"Piksele Meta i Google zbieraj\u0105 dane o zachowaniu u\u017Cytkownika. Umieszczone na podstronie konkretnej us\u0142ugi medycznej mog\u0105 ujawnia\u0107 zainteresowanie okre\u015Blonym leczeniem. Wymagaj\u0105 zgody na cookies zebranej przed uruchomieniem i ostro\u017Cno\u015Bci przy tym, na kt\xF3rych podstronach je w\u0142\u0105czasz."],bullets:["minimalny zakres p\xF3l w formularzu, bez pyta\u0144 o stan zdrowia","klauzula informacyjna i osobna zgoda na kontakt","baner cookies blokuj\u0105cy skrypty marketingowe do momentu zgody","ostro\u017Cno\u015B\u0107 z pikselami na podstronach us\u0142ug wra\u017Cliwych"]},{heading:"Najcz\u0119stsze b\u0142\u0119dy, kt\xF3re widzimy",paragraphs:["Pierwszy: zdj\u0119cia z poczekalni z rozpoznawalnymi pacjentami w tle, publikowane bez zgody. Drugi: odpowied\u017A na negatywn\u0105 opini\u0119 zawieraj\u0105ca szczeg\xF3\u0142y wizyty, czyli ujawnienie danych o zdrowiu w reakcji na krytyk\u0119. Trzeci: baza numer\xF3w telefon\xF3w zebrana w rejestracji, u\u017Cywana do wysy\u0142ki promocji bez zgody marketingowej.","Czwarty jest cichy i najcz\u0119stszy: brak umowy powierzenia z agencj\u0105, kt\xF3ra od dw\xF3ch lat odpowiada na wiadomo\u015Bci pacjent\xF3w w imieniu plac\xF3wki."]}],faq:[{question:"Czy mog\u0119 wysy\u0142a\u0107 pacjentom SMS-y z promocjami?",answer:"Tylko na podstawie zgody marketingowej zebranej wcze\u015Bniej i osobno od zgody na kontakt w sprawie wizyty. Numer podany przy rejestracji s\u0142u\u017Cy do umawiania i przypominania o wizytach - u\u017Cycie go do wysy\u0142ki ofert bez odr\u0119bnej zgody jest naruszeniem."},{question:"Czy mog\u0119 opublikowa\u0107 podzi\u0119kowanie od pacjenta na stronie?",answer:"Tak, je\u015Bli masz pisemn\u0105 zgod\u0119 na publikacj\u0119 tre\u015Bci i - gdy podpisujesz j\u0105 imieniem lub zdj\u0119ciem - tak\u017Ce na wizerunek i dane. Anonimowa opinia bez element\xF3w pozwalaj\u0105cych zidentyfikowa\u0107 osob\u0119 jest bezpieczniejsza, ale mniej wiarygodna dla czytelnika."},{question:"Czy agencja marketingowa potrzebuje umowy powierzenia?",answer:"Tak, je\u017Celi ma dost\u0119p do danych pacjent\xF3w: obs\u0142uguje wiadomo\u015Bci, prowadzi wysy\u0142k\u0119, pracuje w systemie rejestracji albo administruje serwerem ze zg\u0142oszeniami z formularza. Agencja tworz\u0105ca wy\u0142\u0105cznie grafiki bez dost\u0119pu do danych umowy nie wymaga."},{question:"Czy zdj\u0119cia przed i po s\u0105 dozwolone?",answer:"S\u0105 dozwolone przy pisemnej zgodzie pacjenta obejmuj\u0105cej publikacj\u0119 wizerunku i dokumentacji przebiegu leczenia we wskazanych kana\u0142ach. Zdj\u0119cia musz\u0105 pokazywa\u0107 rzeczywisty efekt - obr\xF3bka zmieniaj\u0105ca wynik wprowadza pacjent\xF3w w b\u0142\u0105d i nara\u017Ca plac\xF3wk\u0119 na zarzut nieuczciwej praktyki."}],related:[{path:"/wiedza/jak-zbierac-opinie-pacjentow",label:"Jak zbiera\u0107 opinie pacjent\xF3w zgodnie z prawem",description:"Procedura zbierania opinii bez selekcji i bez nagr\xF3d."},{path:"/uslugi/social-media-dla-klinik",label:"Social media dla klinik",description:"Publikacje i obs\u0142uga wiadomo\u015Bci w granicach ochrony danych."},{path:"/polityka-prywatnosci",label:"Polityka prywatno\u015Bci mediaso",description:"Przyk\u0142ad tego, jak opisujemy przetwarzanie danych u siebie."}]},{slug:"ile-kosztuje-strona-dla-przychodni",title:"Ile kosztuje strona internetowa dla przychodni",h1:"Ile kosztuje strona internetowa dla przychodni",seoTitle:"Ile kosztuje strona internetowa dla przychodni | mediaso",seoDescription:"Wide\u0142ki cenowe stron dla plac\xF3wek medycznych, z czego sk\u0142ada si\u0119 wycena, koszty utrzymania i miejsca, w kt\xF3rych wykonawcy ukrywaj\u0105 koszty.",datePublished:"2026-08-29",dateModified:"2026-08-29",readingMinutes:7,lead:"Strona internetowa dla przychodni kosztuje w Polsce od oko\u0142o 3 000 z\u0142otych netto za prosty serwis gabinetu do kilkudziesi\u0119ciu tysi\u0119cy za rozbudowany portal plac\xF3wki wieloodzia\u0142owej z w\u0142asnym systemem rezerwacji. Rozpi\u0119to\u015B\u0107 bierze si\u0119 z trzech rzeczy: liczby podstron, kt\xF3re kto\u015B musi zaprojektowa\u0107 i napisa\u0107, sposobu umawiania wizyt oraz tego, czy tre\u015Bci powstaj\u0105 od zera, czy plac\xF3wka dostarcza gotowe. Do ceny wykonania dochodz\u0105 koszty sta\u0142e: domena, hosting od 80 z\u0142otych miesi\u0119cznie i opieka techniczna od 250 z\u0142otych miesi\u0119cznie. Poni\u017Cej rozk\u0142adamy wycen\u0119 na cz\u0119\u015Bci, \u017Ceby da\u0142o si\u0119 por\xF3wna\u0107 oferty, kt\xF3re na pierwszy rzut oka r\xF3\u017Cni\u0105 si\u0119 o po\u0142ow\u0119.",sections:[{heading:"Trzy poziomy i realne wide\u0142ki",paragraphs:["Wizyt\xF3wka na gotowym szablonie, do trzech podstron, to 2 900-3 900 z\u0142otych netto: strona g\u0142\xF3wna, opis us\u0142ug, cennik, kontakt z map\u0105 i formularz. Wystarcza praktyce jednoosobowej i nie udaje wi\u0119cej. Termin realizacji 1-2 tygodnie.","Strona z indywidualnym projektem i sze\u015Bcioma podstronami kosztuje 4 900-6 500 z\u0142otych. Tu pojawia si\u0119 praca, kt\xF3rej nie wida\u0107 w wycenie: struktura podstron pod wyszukiwark\u0119, teksty do ka\u017Cdej us\u0142ugi i akceptacja merytoryczna. Wersja z blogiem i systemem zarz\u0105dzania tre\u015Bci\u0105, do dziesi\u0119ciu podstron, to 7 000-11 000 z\u0142otych.","Powy\u017Cej tego poziomu wchodz\u0105 rezerwacje. Osadzenie gotowego systemu typu Booksy czy Calendly kosztuje 1 800-3 500 z\u0142otych. W\u0142asny system rezerwacji z kalendarzem dost\u0119pno\u015Bci, panelem administratora i p\u0142atno\u015Bciami zaczyna si\u0119 od 12 000 z\u0142otych, a przy wielu lokalizacjach i integracjach z oprogramowaniem gabinetowym od 20 000 - i tam cena powstaje dopiero po specyfikacji."],bullets:["wizyt\xF3wka do 3 podstron: 2 900-3 900 z\u0142 netto, 1-2 tygodnie","strona indywidualna do 6 podstron: 4 900-6 500 z\u0142 netto, 2-4 tygodnie","strona z blogiem i CMS do 10 podstron: 7 000-11 000 z\u0142 netto, 3-6 tygodni","osadzenie gotowego systemu rezerwacji: 1 800-3 500 z\u0142 netto","w\u0142asny system rezerwacji: od 12 000 z\u0142 netto"]},{heading:"Co realnie nap\u0119dza cen\u0119",paragraphs:["Liczba unikalnych uk\u0142ad\xF3w strony, a nie liczba podstron. Dwadzie\u015Bcia podstron us\u0142ug na jednym szablonie to jeden projekt i dwadzie\u015Bcia wype\u0142nie\u0144. Pi\u0119\u0107 podstron, z kt\xF3rych ka\u017Cda wygl\u0105da inaczej, to pi\u0119\u0107 projekt\xF3w.","Spos\xF3b umawiania wizyt jest drugim czynnikiem. Formularz zg\u0142oszenia to kilka godzin pracy. Integracja z systemem gabinetowym przez API to dni albo tygodnie, zale\u017Cnie od jako\u015Bci dokumentacji dostawcy - a bywa, \u017Ce integracja jest po prostu niemo\u017Cliwa i trzeba to sprawdzi\u0107 przed podpisaniem umowy.","Trzeci czynnik to tre\u015B\u0107. Napisanie opis\xF3w us\u0142ug medycznych wymaga rozmowy z lekarzem i poprawek po akceptacji. Wykonawca, kt\xF3ry wycenia stron\u0119 bez pytania o to, kto pisze teksty, prawdopodobnie zak\u0142ada, \u017Ce dostarczy je plac\xF3wka."]},{heading:"Koszty, kt\xF3re pojawiaj\u0105 si\u0119 po wdro\u017Ceniu",paragraphs:["Domena to kilkadziesi\u0105t z\u0142otych rocznie i zwykle op\u0142aca j\u0105 plac\xF3wka bezpo\u015Brednio. Hosting z certyfikatem SSL, kopiami zapasowymi i monitoringiem dost\u0119pno\u015Bci kosztuje 80-200 z\u0142otych miesi\u0119cznie, zale\u017Cnie od tego, czy serwis potrzebuje bazy danych.","Opieka techniczna to aktualizacje, kontrola dzia\u0142ania i drobne poprawki. Wariant podstawowy, 250-450 z\u0142otych miesi\u0119cznie, obejmuje do dw\xF3ch godzin pracy; rozszerzony, 700-1 200 z\u0142otych, do pi\u0119ciu godzin z priorytetow\u0105 obs\u0142ug\u0105 i raportem. Przy stronie na systemie CMS to nie jest opcja, tylko warunek bezpiecze\u0144stwa - nieaktualizowana instalacja zostaje zwykle przej\u0119ta w ci\u0105gu kilku miesi\u0119cy.","Nowe funkcje i wi\u0119ksze zmiany rozliczane s\u0105 godzinowo, zwykle po 160-220 z\u0142otych netto za godzin\u0119, z estymacj\u0105 przed rozpocz\u0119ciem prac."],bullets:["domena: kilkadziesi\u0105t z\u0142otych rocznie","hosting z SSL, kopiami i monitoringiem: 80-200 z\u0142 miesi\u0119cznie","opieka techniczna: 250-450 z\u0142 (do 2 h) albo 700-1 200 z\u0142 (do 5 h) miesi\u0119cznie","nowe funkcje i zmiany poza pakietem: 160-220 z\u0142 netto za godzin\u0119"]},{heading:"Gdzie wyceny bywaj\u0105 nieszczere",paragraphs:["Najcz\u0119stszy zabieg to niska cena wykonania i wysoki abonament z blokad\u0105 wyj\u015Bcia: plac\xF3wka nie dostaje dost\u0119pu do kodu ani do hostingu, wi\u0119c przeniesienie strony do innego wykonawcy oznacza budow\u0119 od zera. Pytanie kontrolne przed podpisaniem umowy brzmi: czy dostaj\u0119 pe\u0142ny dost\u0119p do serwera, domeny i kodu.",'Drugi zabieg to \u201ESEO w pakiecie", kt\xF3re okazuje si\u0119 wpisaniem s\u0142\xF3w kluczowych w tytu\u0142y. Trzeci to teksty generowane hurtowo bez konsultacji medycznej - tanie w produkcji, kosztowne, gdy pacjent znajdzie w opisie zabiegu b\u0142\u0105d.']},{heading:"Jak por\xF3wna\u0107 dwie oferty",paragraphs:["Zestaw je na jednej kartce wed\u0142ug: liczby unikalnych projekt\xF3w, tego kto pisze tre\u015Bci, sposobu umawiania wizyt, w\u0142a\u015Bciciela domeny i hostingu, zakresu opieki po wdro\u017Ceniu i terminu realizacji z kar\u0105 za op\xF3\u017Anienie.","R\xF3\u017Cnica w cenie zwykle mie\u015Bci si\u0119 w dw\xF3ch pozycjach: tre\u015Bci i integracji. Je\u015Bli ta\u0144sza oferta ich nie obejmuje, nie jest ta\u0144sza - przenosi koszt na plac\xF3wk\u0119 i na termin uruchomienia."]}],faq:[{question:"Ile kosztuje strona dla gabinetu lekarskiego?",answer:"Serwis gabinetu z opisem us\u0142ug, cennikiem i formularzem kontaktowym mie\u015Bci si\u0119 w przedziale 2 900-3 900 z\u0142otych netto przy trzech podstronach na gotowym szablonie, a 4 900-6 500 z\u0142otych przy indywidualnym projekcie i sze\u015Bciu podstronach. Poni\u017Cej tych kwot dostaje si\u0119 najcz\u0119\u015Bciej szablon z podmienionym logo, bez pracy nad struktur\u0105 i tre\u015Bci\u0105."},{question:"Czy warto p\u0142aci\u0107 abonament za stron\u0119?",answer:"Warto, gdy obejmuje aktualizacje, kopie zapasowe, monitoring i realne wsparcie, a plac\xF3wka zachowuje dost\u0119p do domeny, hostingu i kodu. Nie warto, gdy abonament jest form\u0105 blokady i po jego wypowiedzeniu strona przestaje dzia\u0142a\u0107 albo nie da si\u0119 jej przenie\u015B\u0107."},{question:"Ile trwa budowa strony dla przychodni?",answer:"Od 1-2 tygodni przy prostej wizyt\xF3wce do 3-6 tygodni przy stronie z blogiem i systemem zarz\u0105dzania tre\u015Bci\u0105, licz\u0105c od kompletu materia\u0142\xF3w. W\u0142asny system rezerwacji to dodatkowe 5-8 tygodni. Termin wyd\u0142u\u017Ca si\u0119 najcz\u0119\u015Bciej przez oczekiwanie na materia\u0142y plac\xF3wki: zdj\u0119cia zespo\u0142u, zatwierdzony cennik i akceptacj\u0119 opis\xF3w us\u0142ug."}],related:[{path:"/uslugi/strony-internetowe-dla-placowek-medycznych",label:"Strony internetowe dla plac\xF3wek medycznych",description:"Zakres, harmonogram i wide\u0142ki cenowe naszej realizacji."},{path:"/wiedza/pozycjonowanie-kliniki-krok-po-kroku",label:"Pozycjonowanie kliniki krok po kroku",description:"Strona bez widoczno\u015Bci w Google nie zwraca si\u0119 nigdy."},{path:"/kontakt",label:"Kontakt",description:"Opisz zakres, ode\u015Blemy wycen\u0119 z rozbiciem na pozycje."}]},{slug:"jak-zbierac-opinie-pacjentow",title:"Jak zbiera\u0107 opinie pacjent\xF3w zgodnie z prawem",h1:"Jak zbiera\u0107 opinie pacjent\xF3w zgodnie z prawem",seoTitle:"Jak zbiera\u0107 opinie pacjent\xF3w w Google - procedura | mediaso",seoDescription:"Procedura zbierania opinii pacjent\xF3w: kiedy prosi\u0107, jak formu\u0142owa\u0107 pro\u015Bb\u0119, czego nie wolno robi\u0107 i jak odpowiada\u0107 na negatywne opinie bez \u0142amania RODO.",datePublished:"2026-08-29",dateModified:"2026-08-29",readingMinutes:6,lead:"Opinie w Google s\u0105 w ochronie zdrowia jednym z najmocniejszych czynnik\xF3w decyzji: pacjent czyta je przed pierwszym telefonem, a plac\xF3wka z dwudziestoma \u015Bwie\u017Cymi opiniami wygrywa z plac\xF3wk\u0105 z trzema sprzed czterech lat. Zbieranie opinii jest dozwolone i sensowne, ale ma trzy twarde ograniczenia. Nie wolno wybiera\u0107, kogo si\u0119 pyta, na podstawie przewidywanej oceny. Nie wolno oferowa\u0107 niczego w zamian - ani zni\u017Cki, ani drobnego upominku. Nie wolno publicznie potwierdza\u0107, \u017Ce autor opinii by\u0142 pacjentem, bo to ujawnia informacj\u0119 o jego zdrowiu. Reszta to kwestia procedury: kiedy wys\u0142a\u0107 pro\u015Bb\u0119, jak j\u0105 sformu\u0142owa\u0107, kto odpowiada na opinie i w jakim czasie. Poni\u017Cej gotowy proces do wdro\u017Cenia w rejestracji.",sections:[{heading:"Kiedy prosi\u0107 o opini\u0119",paragraphs:["Najlepszy moment to jeden do dw\xF3ch dni po wizycie - pacjent pami\u0119ta wizyt\u0119, a emocje z poczekalni ju\u017C opad\u0142y. Pro\u015Bba tego samego dnia cz\u0119\u015Bciej trafia w rozdra\u017Cnienie po oczekiwaniu, a po tygodniu wizyta jest ju\u017C ma\u0142o istotna.","Przy leczeniu roz\u0142o\u017Conym w czasie, jak ortodoncja czy implanty, sensowniejszy jest moment zako\u0144czenia etapu, nie pierwszej konsultacji. Pacjent ma wtedy co oceni\u0107."]},{heading:"Do kogo kierowa\u0107 pro\u015Bb\u0119",paragraphs:["Do wszystkich pacjent\xF3w z danej grupy, bez wyj\u0105tk\xF3w. Wybieranie tych, kt\xF3rzy wygl\u0105dali na zadowolonych, jest sterowaniem ocen\u0105 i \u0142amie zasady Google, a wykryte ko\u0144czy si\u0119 utrat\u0105 cz\u0119\u015Bci opinii albo zawieszeniem profilu.","Praktycznie oznacza to prost\u0105 regu\u0142\u0119 w rejestracji: pro\u015Bba wychodzi automatycznie do ka\u017Cdego, kto by\u0142 na wizycie danego typu i wyrazi\u0142 zgod\u0119 na kontakt. Bez decyzji cz\u0142owieka o tym, kogo pomin\u0105\u0107."],bullets:["pro\u015Bba do ca\u0142ej grupy pacjent\xF3w, bez selekcji","\u017Cadnych zni\u017Cek, upomink\xF3w ani punkt\xF3w w zamian za opini\u0119","jeden kana\u0142 kontaktu, ustalony i zapisany w procedurze","brak ponagle\u0144 - jedna pro\u015Bba wystarczy"]},{heading:"Jak sformu\u0142owa\u0107 pro\u015Bb\u0119",paragraphs:['Kr\xF3tko, z bezpo\u015Brednim linkiem do formularza opinii i bez sugerowania oceny. Zdanie \u201Eb\u0119dzie nam mi\u0142o, je\u015Bli wystawisz pi\u0119\u0107 gwiazdek" jest ju\u017C sterowaniem. Poprawna wersja prosi o opini\u0119, nie o dobr\u0105 opini\u0119.','Wz\xF3r, kt\xF3ry dzia\u0142a: \u201EDzi\u0119kujemy za wizyt\u0119 w [nazwa plac\xF3wki]. Je\u015Bli ma Pani/Pan chwil\u0119, prosimy o opini\u0119 o naszej pracy: [link]. Opinie pomagaj\u0105 nam poprawia\u0107 obs\u0142ug\u0119." Bez emocji, bez nacisku, bez obietnic.']},{heading:"Odpowiadanie na opinie, w tym negatywne",paragraphs:["Odpowiadaj na wszystkie, w ci\u0105gu kilku dni roboczych. Przy opinii pozytywnej wystarczy podzi\u0119kowanie bez odnoszenia si\u0119 do przebiegu leczenia. Przy negatywnej obowi\u0105zuje zasada, kt\xF3ra wygl\u0105da niewygodnie: nie potwierdzasz, \u017Ce autor by\u0142 pacjentem, i nie prostujesz publicznie fakt\xF3w medycznych.","Bezpieczny wz\xF3r: podzi\u0119kowanie za sygna\u0142, informacja, \u017Ce plac\xF3wka traktuje uwagi powa\u017Cnie, i zaproszenie do kontaktu bezpo\u015Bredniego pod wskazany adres lub numer. Wyja\u015Bnienia prowadzisz poza publiczn\u0105 cz\u0119\u015Bci\u0105. Opinie ewidentnie fa\u0142szywe albo obra\u017Aliwe zg\u0142aszasz do platformy, zamiast wdawa\u0107 si\u0119 w sp\xF3r."],bullets:["odpowied\u017A na ka\u017Cd\u0105 opini\u0119 w kilka dni roboczych","brak publicznego potwierdzenia, \u017Ce autor by\u0142 pacjentem","\u017Cadnych szczeg\xF3\u0142\xF3w leczenia w odpowiedzi","zaproszenie do kontaktu bezpo\u015Bredniego zamiast dyskusji pod opini\u0105","zg\u0142oszenie do platformy przy naruszeniu jej zasad"]},{heading:"Co mierzy\u0107",paragraphs:["Trzy liczby wystarcz\u0105: \u015Brednia ocena, liczba nowych opinii w miesi\u0105cu i odsetek opinii z odpowiedzi\u0105. Tempo przyrostu ma dla widoczno\u015Bci wi\u0119ksze znaczenie ni\u017C sama \u015Brednia - profil z opiniami sprzed trzech lat wygl\u0105da na porzucony.","Realny cel dla plac\xF3wki uruchamiaj\u0105cej proces od zera to kilka nowych opinii miesi\u0119cznie. Skok z trzech do pi\u0119\u0107dziesi\u0119ciu w miesi\u0105c jest sygna\u0142em ostrzegawczym dla algorytmu i bywa ko\u0144czony masowym usuni\u0119ciem."]}],faq:[{question:"Czy mo\u017Cna prosi\u0107 pacjent\xF3w o opinie w Google?",answer:"Tak. Google zabrania natomiast oferowania korzy\u015Bci w zamian za opini\u0119 oraz zbierania opinii wy\u0142\u0105cznie od wybranych, zadowolonych pacjent\xF3w. Pro\u015Bba skierowana do wszystkich pacjent\xF3w z danej grupy, bez nagrody, jest zgodna z zasadami."},{question:"Czy plac\xF3wka mo\u017Ce odpowiada\u0107 na negatywne opinie?",answer:"Mo\u017Ce i powinna, ale bez potwierdzania, \u017Ce autor by\u0142 pacjentem, i bez odnoszenia si\u0119 do przebiegu leczenia. Publiczne przywo\u0142anie szczeg\xF3\u0142\xF3w wizyty jest ujawnieniem danych o zdrowiu, nawet je\u015Bli to autor opinii zacz\u0105\u0142 o nich pisa\u0107."},{question:"Czy mo\u017Cna usun\u0105\u0107 niesprawiedliw\u0105 opini\u0119?",answer:"Plac\xF3wka mo\u017Ce zg\u0142osi\u0107 j\u0105 do platformy jako naruszenie zasad - na przyk\u0142ad gdy zawiera dane osobowe, tre\u015Bci obra\u017Aliwe lub dotyczy innej firmy. Google rozpatruje zg\u0142oszenia indywidualnie i nie usuwa opinii tylko dlatego, \u017Ce jest negatywna."},{question:"Ile opinii potrzebuje plac\xF3wka?",answer:"Liczy si\u0119 nie tyle \u0142\u0105czna liczba, co regularny dop\u0142yw. Kilka nowych opinii miesi\u0119cznie utrzymuje profil w rotacji i pokazuje pacjentowi, \u017Ce plac\xF3wka dzia\u0142a. Nag\u0142y skok z kilku do kilkudziesi\u0119ciu w kr\xF3tkim czasie bywa oznaczany jako podejrzany."}],related:[{path:"/uslugi/wizytowka-google-dla-placowki",label:"Wizyt\xF3wka Google dla plac\xF3wki",description:"Opinie s\u0105 jednym z trzech filar\xF3w widoczno\u015Bci w mapach."},{path:"/wiedza/rodo-w-marketingu-placowki-medycznej",label:"RODO w marketingu plac\xF3wki medycznej",description:"Zgody i granice publikowania informacji o pacjentach."}]}];var o=[{slug:"pozycjonowanie-klinik",navLabel:"Pozycjonowanie klinik",h1:"Pozycjonowanie klinik i przychodni",seoTitle:"Pozycjonowanie klinik i przychodni (SEO medyczne) | mediaso",seoDescription:"SEO dla klinik, przychodni i gabinet\xF3w: audyt od 1 000 z\u0142 netto, podstrony us\u0142ug i lokalizacji, wizyt\xF3wka Google, tre\u015Bci zgodne z zasadami bran\u017Cy.",schemaName:"Pozycjonowanie stron plac\xF3wek medycznych",schemaServiceType:"SEO dla bran\u017Cy medycznej",pricing:[{title:"Pozycjonowanie",rows:[{name:"Audyt i optymalizacja SEO na start",price:"1 000 \u2013 2 500 z\u0142",scope:"analiza techniczna, podstawowe rekomendacje i wdro\u017Cenie uzgodnionych poprawek"},{name:"Nowe podstrony us\u0142ug i lokalizacji",price:"160 \u2013 220 z\u0142/h",scope:"rozbudowa serwisu po estymacji; przy nowej stronie w cenie pakietu"},{name:"Opieka Pro",price:"700 \u2013 1 200 z\u0142/mies.",scope:"do 5 godzin pracy w miesi\u0105cu, priorytetowa obs\u0142uga, comiesi\u0119czny raport"},{name:"Konsultacja techniczna",price:"160 \u2013 220 z\u0142/h",scope:"analiza problemu, rekomendacja lub plan wdro\u017Cenia"}]}],lead:'Pozycjonowanie kliniki polega na tym, \u017Ceby strona plac\xF3wki pojawia\u0142a si\u0119 w Google wtedy, gdy pacjent szuka konkretnej us\u0142ugi w konkretnym mie\u015Bcie. W praktyce oznacza to trzy rzeczy naraz: osobn\u0105 podstron\u0119 dla ka\u017Cdej us\u0142ugi, kt\xF3r\u0105 plac\xF3wka realnie sprzedaje, uporz\u0105dkowan\u0105 wizyt\xF3wk\u0119 Google spi\u0119t\u0105 z tymi podstronami oraz techniczn\u0105 stron\u0119 serwisu, kt\xF3r\u0105 Google potrafi przeczyta\u0107 i szybko wy\u015Bwietli\u0107 na telefonie. Najwi\u0119kszy ruch w medycynie jest lokalny i bardzo konkretny: \u201Eortodonta Wroc\u0142aw Krzyki", \u201EUSG jamy brzusznej Pozna\u0144", \u201Eendokrynolog prywatnie Gda\u0144sk". Jedna strona z list\u0105 wszystkich us\u0142ug nie wygra \u017Cadnego z tych zapyta\u0144, bo odpowiada na wszystkie po trochu. Prowadzimy pozycjonowanie w modelu: audyt, architektura podstron, tre\u015Bci, wdro\u017Cenie techniczne, comiesi\u0119czne raportowanie pozycji i telefon\xF3w z Google.',sections:[{heading:"Od czego zaczynamy: audyt zamiast obietnic",paragraphs:["Pierwsze dwa tygodnie to praca na danych plac\xF3wki, nie na szablonie. Sprawdzamy, na jakie frazy strona ju\u017C si\u0119 wy\u015Bwietla w Search Console, kt\xF3re podstrony przynosz\u0105 telefony, jak wygl\u0105da wizyt\xF3wka Google w por\xF3wnaniu z trzema najbli\u017Cszymi konkurentami i co blokuje indeksowanie po stronie technicznej.","Z audytu wychodzi lista fraz podzielona na trzy koszyki: zapytania, na kt\xF3rych plac\xF3wka jest blisko pierwszej dziesi\u0105tki i wystarczy je dopchn\u0105\u0107, zapytania wymagaj\u0105ce nowej podstrony oraz zapytania, kt\xF3rych nie warto atakowa\u0107, bo kupuje je sie\u0107 medyczna z bud\u017Cetem niepor\xF3wnywalnym z lokaln\u0105 przychodni\u0105. Ten trzeci koszyk jest r\xF3wnie wa\u017Cny - oszcz\u0119dza miesi\u0105ce pracy."],bullets:["analiza widoczno\u015Bci w Google Search Console i pozycji na frazy us\u0142ugowe","por\xF3wnanie wizyt\xF3wki Google z konkurencj\u0105 w promieniu obs\u0142ugiwanego obszaru","audyt techniczny: indeksowanie, szybko\u015B\u0107 na telefonie, dane strukturalne","mapa fraz z podzia\u0142em na us\u0142ugi, lokalizacje i pytania pacjent\xF3w"]},{heading:"Architektura podstron: jedna us\u0142uga, jeden adres",paragraphs:['Google przypisuje wynik do adresu URL, nie do domeny. Je\u017Celi implantologia, ortodoncja i higienizacja mieszkaj\u0105 na jednej podstronie \u201EUs\u0142ugi", strona konkuruje sama ze sob\u0105 i przegrywa z gabinetem, kt\xF3ry ma trzy osobne adresy. Rozbijamy ofert\u0119 na podstrony i pilnujemy, \u017Ceby ka\u017Cda odpowiada\u0142a na inne pytanie pacjenta.',"Ka\u017Cda podstrona us\u0142ugi dostaje opis przebiegu wizyty, przygotowanie pacjenta, przeciwwskazania, orientacyjny czas i cen\u0119 oraz sekcj\u0119 pyta\u0144. Przy plac\xF3wkach wieloodzia\u0142owych dok\u0142adamy warstw\u0119 lokalizacji: osobny adres dla ka\u017Cdego oddzia\u0142u z godzinami, parkingiem, dojazdem i zespo\u0142em. Struktura linkowania trzyma to razem - z us\u0142ugi do oddzia\u0142u i z oddzia\u0142u do us\u0142ug, kt\xF3re w nim realnie dzia\u0142aj\u0105."],bullets:["osobna podstrona dla ka\u017Cdej us\u0142ugi kupowanej przez pacjenta","strony oddzia\u0142\xF3w dla plac\xF3wek z kilkoma adresami","linkowanie wewn\u0119trzne mi\u0119dzy us\u0142ug\u0105, oddzia\u0142em i specjalist\u0105","dane strukturalne MedicalBusiness i FAQ na podstronach us\u0142ug"]},{heading:"Tre\u015B\u0107, kt\xF3ra przechodzi przez wymagania bran\u017Cy medycznej",paragraphs:["Reklama i prezentacja us\u0142ug medycznych podlega ograniczeniom, kt\xF3rych nie ma w innych bran\u017Cach - obowi\u0105zuj\u0105 mi\u0119dzy innymi przepisy o zawodach lekarza i lekarza dentysty oraz zasady kodeksu etyki lekarskiej dotycz\u0105ce tre\u015Bci reklamowych. Nie obiecujemy w tekstach wynik\xF3w leczenia, nie budujemy przekazu na por\xF3wnaniach z konkretnymi konkurentami i nie publikujemy zdj\u0119\u0107 pacjent\xF3w bez pisemnej zgody.","Tre\u015Bci opiniuje osoba merytoryczna po stronie plac\xF3wki. To nie jest formalno\u015B\u0107: opis zabiegu napisany przez copywritera bez konsultacji z lekarzem prowadz\u0105cym potrafi zawiera\u0107 b\u0142\u0105d, kt\xF3ry kosztuje wiarygodno\u015B\u0107 u pacjenta i u Google. Publikujemy dopiero po akceptacji."]},{heading:"Jak to wyceniamy",paragraphs:['Zaczynamy od pozycji \u201Eaudyt i optymalizacja SEO na start": 1 000-2 500 z\u0142 netto. Obejmuje analiz\u0119 techniczn\u0105, list\u0119 fraz, rekomendacje i wdro\u017Cenie uzgodnionych poprawek na istniej\u0105cej stronie. Po audycie wiadomo, co dalej ma sens - i dopiero wtedy powstaje wycena.',"Rozbudowa serwisu o podstrony us\u0142ug i lokalizacji rozliczana jest jako praca nad stron\u0105, po 160-220 z\u0142 netto za godzin\u0119 albo w ramach pakietu, je\u015Bli stron\u0119 budujemy od zera. Sta\u0142a opieka nad widoczno\u015Bci\u0105 mie\u015Bci si\u0119 w pakiecie Opieka Pro, 700-1 200 z\u0142 miesi\u0119cznie, razem z comiesi\u0119cznym raportem wykonanych prac."]},{heading:"Czego realnie oczekiwa\u0107 i kiedy",paragraphs:["SEO nie dzia\u0142a w tydzie\u0144. Pierwsze ruchy pozycji na frazy o niskiej konkurencji wida\u0107 zwykle po 6-10 tygodniach od wdro\u017Cenia zmian technicznych i publikacji podstron. Frazy og\xF3lne w du\u017Cym mie\u015Bcie to horyzont kilku kwarta\u0142\xF3w i nie ma sensu obiecywa\u0107 inaczej.","Podstawowa optymalizacja nie jest gwarancj\u0105 pozycji, ruchu ani liczby zapyta\u0144 - wynik zale\u017Cy te\u017C od konkurencji, tre\u015Bci, bud\u017Cetu i historii domeny. To, co mo\u017Cemy obieca\u0107, to wykonana praca i jej rozliczenie: pozycje na uzgodnionej li\u015Bcie fraz, wej\u015Bcia z wyszukiwarki oraz telefony i klikni\u0119cia w tras\u0119 z wizyt\xF3wki Google."]}],faq:[{question:"Ile trwa pozycjonowanie kliniki, zanim wida\u0107 efekty?",answer:"Pierwsze wzrosty pozycji na frazy lokalne i mniej konkurencyjne pojawiaj\u0105 si\u0119 zwykle po 6-10 tygodniach od wdro\u017Cenia zmian. Frazy og\xF3lne w du\u017Cych miastach wymagaj\u0105 zwykle 6-12 miesi\u0119cy systematycznej pracy. Ka\u017Cdy, kto obiecuje pierwsze miejsce w miesi\u0105c, sprzedaje co\u015B innego ni\u017C SEO."},{question:"Czy pozycjonowanie kliniki jest zgodne z zakazem reklamy us\u0142ug medycznych?",answer:"Tak, o ile tre\u015Bci trzymaj\u0105 si\u0119 ogranicze\u0144 bran\u017Cowych. Publikujemy rzetelne informacje o zakresie us\u0142ug, przebiegu wizyty i cenach, nie obiecujemy skutk\xF3w leczenia i nie budujemy przekazu na por\xF3wnaniach z konkretnymi plac\xF3wkami. Ka\u017Cdy tekst medyczny akceptuje osoba merytoryczna po stronie plac\xF3wki."},{question:"Ile kosztuje audyt SEO plac\xF3wki?",answer:"Audyt i optymalizacja SEO na start to 1 000-2 500 z\u0142 netto: analiza techniczna, lista fraz, rekomendacje i wdro\u017Cenie uzgodnionych poprawek. Dalsze prace - nowe podstrony us\u0142ug, tre\u015Bci, sta\u0142a opieka - wyceniamy dopiero po audycie, bo wcze\u015Bniej nie wiadomo, ile ich potrzeba."},{question:"Czy potrzebuj\u0119 nowej strony, \u017Ceby zacz\u0105\u0107 pozycjonowanie?",answer:"Nie zawsze. Je\u017Celi obecna strona jest indeksowana, dzia\u0142a na telefonie i da si\u0119 do niej dopisywa\u0107 podstrony, pracujemy na niej. Now\u0105 stron\u0119 rekomendujemy, gdy serwis nie ma systemu zarz\u0105dzania tre\u015Bci\u0105, \u0142aduje si\u0119 kilka sekund albo jest zbudowany tak, \u017Ce Google nie widzi jego tre\u015Bci."},{question:"Co z plac\xF3wk\u0105, kt\xF3ra ma kilka oddzia\u0142\xF3w?",answer:"Ka\u017Cdy oddzia\u0142 dostaje w\u0142asn\u0105 podstron\u0119 z adresem, godzinami, zespo\u0142em i list\u0105 us\u0142ug realizowanych na miejscu, a tak\u017Ce osobn\u0105 wizyt\xF3wk\u0119 Google. Bez tego oddzia\u0142y konkuruj\u0105 ze sob\u0105 w wynikach lokalnych i \u017Caden nie wychodzi wysoko."}],related:[{path:"/uslugi/strony-internetowe-dla-placowek-medycznych",label:"Strony internetowe dla plac\xF3wek medycznych",description:"Podstrony us\u0142ug i lokalizacji, kt\xF3re da si\u0119 pozycjonowa\u0107."},{path:"/uslugi/wizytowka-google-dla-placowki",label:"Wizyt\xF3wka Google dla plac\xF3wki",description:"Lokalne wyniki i mapy - druga po\u0142owa widoczno\u015Bci w Google."},{path:"/wiedza/pozycjonowanie-kliniki-krok-po-kroku",label:"Pozycjonowanie kliniki krok po kroku",description:"Kolejno\u015B\u0107 dzia\u0142a\u0144 opisana tak, \u017Ceby da\u0142o si\u0119 j\u0105 zrobi\u0107 samodzielnie."}]},{slug:"strony-internetowe-dla-placowek-medycznych",navLabel:"Strony internetowe",h1:"Strony internetowe dla plac\xF3wek medycznych",seoTitle:"Strony internetowe dla przychodni i klinik | mediaso",seoDescription:"Strony dla przychodni, klinik i gabinet\xF3w: od 2 900 z\u0142 netto, podstrony us\u0142ug, rezerwacja wizyt, CMS, RODO. Realizacja od 1 do 6 tygodni.",schemaName:"Strony internetowe dla plac\xF3wek medycznych",schemaServiceType:"Tworzenie stron internetowych",priceFrom:"2900",pricing:[{title:"Pakiety stron",rows:[{name:"Wizyt\xF3wka Basic",price:"2 900 \u2013 3 900 z\u0142",scope:"do 3 podstron, gotowy szablon, formularz kontaktowy, podstawowe SEO, 1 runda poprawek; 1\u20132 tygodnie"},{name:"Wizyt\xF3wka Custom",price:"4 900 \u2013 6 500 z\u0142",scope:"do 6 podstron, indywidualny wygl\u0105d, mapa, galeria, opinie, SEO on-page, 2 rundy poprawek; 2\u20134 tygodnie"},{name:"Strona firmowa z blogiem i CMS",price:"7 000 \u2013 11 000 z\u0142",scope:"do 10 podstron, system CMS, blog, szkolenie z obs\u0142ugi, 2 rundy poprawek; 3\u20136 tygodni"}]},{title:"Rezerwacja wizyt i p\u0142atno\u015Bci",rows:[{name:"Integracja gotowego systemu rezerwacji",price:"1 800 \u2013 3 500 z\u0142",scope:"Booksy, Calendly, SimplyBook.me lub podobny; do 5 us\u0142ug; 3\u20137 dni roboczych"},{name:"Dedykowany system rezerwacji Basic",price:"12 000 \u2013 18 000 z\u0142",scope:"kalendarz, do 10 us\u0142ug i 5 pracownik\xF3w, panel administratora, e-maile; 5\u20138 tygodni"},{name:"Dedykowany system rezerwacji Pro",price:"od 20 000 z\u0142",scope:"wiele lokalizacji, role, integracje; cena po specyfikacji"},{name:"Integracja p\u0142atno\u015Bci online",price:"1 200 \u2013 2 500 z\u0142",scope:"jedna bramka (Przelewy24, Stripe, PayU), do 3 metod p\u0142atno\u015Bci"}]},{title:"Utrzymanie",rows:[{name:"Hosting",price:"80 \u2013 200 z\u0142/mies.",scope:"SSL, kopie zapasowe, monitoring dost\u0119pno\u015Bci; domena osobno"},{name:"Opieka Basic",price:"250 \u2013 450 z\u0142/mies.",scope:"do 2 godzin pracy w miesi\u0105cu: aktualizacje, kopie, drobne poprawki"},{name:"Opieka Pro",price:"700 \u2013 1 200 z\u0142/mies.",scope:"do 5 godzin pracy w miesi\u0105cu, priorytet, raport, konsultacja do 30 minut"},{name:"Rozw\xF3j systemu",price:"160 \u2013 220 z\u0142/h",scope:"nowe funkcje i wi\u0119ksze zmiany, zawsze po estymacji"}]},{title:"Dodatkowo",rows:[{name:"Migracja z innej platformy",price:"od 40% ceny projektu",scope:"wycena po sprawdzeniu danych, hostingu i mo\u017Cliwo\u015Bci eksportu"},{name:"Wprowadzenie tre\u015Bci",price:"30 \u2013 80 z\u0142/szt.",scope:"zale\u017Cnie od liczby p\xF3l, zdj\u0119\u0107 i \u017Ar\xF3d\u0142a danych"},{name:"Dodatkowa runda poprawek",price:"160 \u2013 220 z\u0142/h",scope:"prace poza liczb\u0105 rund zawart\u0105 w pakiecie"}]}],lead:'Strona plac\xF3wki medycznej ma do wykonania trzy zadania i wszystko poza nimi jest dodatkiem. Ma pozwoli\u0107 pacjentowi um\xF3wi\u0107 wizyt\u0119 w kilka sekund, odpowiedzie\u0107 na pytania, kt\xF3re w innym wypadku trafi\u0142yby do rejestracji, i pokaza\u0107 si\u0119 w Google wtedy, gdy kto\u015B szuka konkretnej us\u0142ugi w okolicy. Wi\u0119kszo\u015B\u0107 stron przychodni przegrywa na pierwszym punkcie: numer telefonu jest w stopce, formularz ma dziewi\u0119\u0107 p\xF3l, a godziny otwarcia le\u017C\u0105 w PDF-ie. Budujemy strony wok\xF3\u0142 \u015Bcie\u017Cki pacjenta, nie wok\xF3\u0142 struktury organizacyjnej plac\xF3wki - bo pacjent nie szuka \u201Edzia\u0142u diagnostyki obrazowej", tylko USG kolana na przysz\u0142y tydzie\u0144. Do tego dochodz\u0105 rzeczy niewidoczne: szybko\u015B\u0107 \u0142adowania na telefonie w s\u0142abym zasi\u0119gu, dost\u0119pno\u015B\u0107 dla os\xF3b starszych i formularze zgodne z RODO.',sections:[{heading:"Co ma by\u0107 na stronie przychodni",paragraphs:["Zestaw obowi\u0105zkowy jest kr\xF3tki i prawie zawsze niekompletny w istniej\u0105cych serwisach. Telefon widoczny bez przewijania i klikalny na telefonie. Godziny przyj\u0119\u0107 jako tekst, nie obrazek. Adres z map\u0105 i informacj\u0105 o parkingu. Cennik albo przynajmniej przedzia\u0142y cenowe. Lista specjalist\xF3w z tym, co realnie przyjmuj\u0105.","Dalej idzie warstwa, kt\xF3ra zdejmuje prac\u0119 z rejestracji: przygotowanie do bada\u0144, wymagane dokumenty, zasady odwo\u0142ywania wizyt, informacja o teleporadach. Ka\u017Cde z tych pyta\u0144 zadawane jest przez telefon kilkana\u015Bcie razy dziennie w \u015Bredniej przychodni."],bullets:["klikalny telefon i przycisk um\xF3wienia wizyty na ka\u017Cdym ekranie","osobna podstrona ka\u017Cdej us\u0142ugi z cen\u0105 i przebiegiem wizyty","strony oddzia\u0142\xF3w i specjalist\xF3w przy plac\xF3wkach wieloosobowych","przygotowanie do bada\u0144 i dokumenty do pobrania","formularz kontaktowy z klauzul\u0105 RODO i zgod\u0105 na kontakt"]},{heading:"Umawianie wizyt: integracja albo prosty formularz",paragraphs:["Je\u017Celi plac\xF3wka pracuje na systemie gabinetowym z modu\u0142em e-rejestracji, spinamy stron\u0119 z tym systemem i nie budujemy drugiego, konkurencyjnego kalendarza. Podw\xF3jny grafik to gwarancja podw\xF3jnej rezerwacji tego samego terminu.","Gdy integracja nie wchodzi w gr\u0119, robimy formularz zg\u0142oszenia wizyty: us\u0142uga, preferowany termin, dane kontaktowe i zgoda na kontakt. Zg\u0142oszenie idzie mailem do rejestracji, a pacjent dostaje jasn\u0105 informacj\u0119, \u017Ce to pro\u015Bba o kontakt, nie potwierdzona rezerwacja. Uczciwy komunikat oszcz\u0119dza reklamacji."]},{heading:"Technologia i utrzymanie",paragraphs:["Strony budujemy jako serwisy statyczne albo na sprawdzonym systemie CMS, zale\u017Cnie od tego, kto i jak cz\u0119sto b\u0119dzie aktualizowa\u0142 tre\u015B\u0107. Plac\xF3wka dostaje dost\u0119p do edycji cennika, godzin i aktualno\u015Bci bez dzwonienia do agencji.","Po\u0142\u0105czenie idzie po HTTPS, a formularze zapisuj\u0105 tylko te dane, kt\xF3re s\u0105 potrzebne do odpowiedzi. Kopie zapasowe i monitoring dost\u0119pno\u015Bci wchodz\u0105 w hosting, aktualizacje oprogramowania w pakiet opieki technicznej. Po op\u0142aceniu ca\u0142o\u015Bci wynagrodzenia plac\xF3wka dostaje uzgodnione w umowie prawa i dost\u0119py do projektu."],bullets:["panel do samodzielnej edycji tre\u015Bci, cennika i godzin","certyfikat SSL, kopie zapasowe i monitoring dost\u0119pno\u015Bci w ramach hostingu","wynik Core Web Vitals mierzony po wdro\u017Ceniu, nie deklarowany","opieka techniczna z aktualizacjami i monitoringiem dost\u0119pno\u015Bci"]},{heading:"Pakiety, terminy i ceny",paragraphs:["Pracujemy na trzech pakietach. Cena pakietowa obowi\u0105zuje w granicach opisanych limit\xF3w - liczba podstron, formularzy i rund poprawek jest maksymalna, nie orientacyjna. Wszystkie kwoty s\u0105 netto, termin liczy si\u0119 od otrzymania kompletu materia\u0142\xF3w i zaliczki.","Wizyt\xF3wka Basic, 2 900-3 900 z\u0142, do 3 podstron, gotowy szablon dopasowany do marki, formularz kontaktowy, podstawowe SEO on-page, jedna runda poprawek. Termin 1-2 tygodnie. Wystarcza praktyce jednoosobowej i gabinetowi, kt\xF3ry potrzebuje adresu, cennika i telefonu w widocznym miejscu.","Wizyt\xF3wka Custom, 4 900-6 500 z\u0142, do 6 podstron, indywidualny uk\u0142ad i typografia, mapa Google, galeria, sekcja opinii, dwie rundy poprawek. Termin 2-4 tygodnie. To najcz\u0119stszy wyb\xF3r przychodni, kt\xF3ra chce osobn\u0105 podstron\u0119 dla ka\u017Cdej z kilku us\u0142ug.","Strona firmowa z blogiem i CMS, 7 000-11 000 z\u0142, do 10 podstron, wdro\u017Cenie systemu zarz\u0105dzania tre\u015Bci\u0105, blog z kategoriami i wyszukiwaniem, integracja z dwoma profilami spo\u0142eczno\u015Bciowymi, szkolenie z obs\u0142ugi. Termin 3-6 tygodni. Dla plac\xF3wki, kt\xF3ra sama chce publikowa\u0107 i rozbudowywa\u0107 serwis."],note:"Cena pakietowa nie obejmuje przygotowania tekst\xF3w, zdj\u0119\u0107 i identyfikacji wizualnej ani dokument\xF3w prawnych. Prace poza pakietem rozliczamy po 160-220 z\u0142 netto za godzin\u0119, zawsze po wcze\u015Bniejszej estymacji."},{heading:"Rezerwacja wizyt i p\u0142atno\u015Bci",paragraphs:["Je\u017Celi plac\xF3wka korzysta z gotowego systemu rezerwacji, osadzamy go na stronie: konfiguracja wid\u017Cetu, do 5 us\u0142ug lub typ\xF3w wizyt, powiadomienia i testy na telefonie. Koszt 1 800-3 500 z\u0142, termin 3-7 dni roboczych. Abonament samego systemu op\u0142aca plac\xF3wka osobno.","Gdy gotowe narz\u0119dzie nie wystarcza, budujemy dedykowany system rezerwacji. Wariant Basic, 12 000-18 000 z\u0142, obejmuje publiczny kalendarz dost\u0119pno\u015Bci, do 10 us\u0142ug i 5 pracownik\xF3w lub gabinet\xF3w, panel administratora, potwierdzenia e-mail i jedn\u0105 bramk\u0119 p\u0142atno\u015Bci. Termin 5-8 tygodni. Wariant Pro, od 20 000 z\u0142, dotyczy wielu lokalizacji, rozbudowanych r\xF3l i integracji - tu najpierw powstaje specyfikacja i harmonogram, dopiero potem cena.","Integracja p\u0142atno\u015Bci online, je\u015Bli plac\xF3wka pobiera przedp\u0142aty za wizyty komercyjne: 1 200-2 500 z\u0142 za jedn\u0105 bramk\u0119 i do trzech metod p\u0142atno\u015Bci. Prowizje operatora s\u0105 poza t\u0105 kwot\u0105."]},{heading:"Utrzymanie po wdro\u017Ceniu",paragraphs:["Hosting z certyfikatem SSL, kopiami zapasowymi i monitoringiem dost\u0119pno\u015Bci: 80-200 z\u0142 miesi\u0119cznie, zale\u017Cnie od rodzaju strony. Domen\u0119 plac\xF3wka op\u0142aca we w\u0142asnym zakresie.","Opieka Basic, 250-450 z\u0142 miesi\u0119cznie, obejmuje do 2 godzin pracy: aktualizacje, kontrol\u0119 dzia\u0142ania, kopie i drobne poprawki tre\u015Bci. Opieka Pro, 700-1 200 z\u0142 miesi\u0119cznie, to do 5 godzin, priorytetowa obs\u0142uga, comiesi\u0119czny raport wykonanych prac i konsultacja. Niewykorzystane godziny nie przechodz\u0105 na kolejny miesi\u0105c.","Nowe funkcje i wi\u0119ksze zmiany rozliczamy po 160-220 z\u0142 netto za godzin\u0119. Przed rozpocz\u0119ciem dostajesz opis zadania, szacowany czas albo cen\u0119 maksymaln\u0105 i termin. Przez 30 dni od publikacji bezp\u0142atnie usuwamy b\u0142\u0119dy wynikaj\u0105ce z niezgodno\u015Bci z uzgodnionym zakresem."]}],faq:[{question:"Ile kosztuje strona internetowa dla przychodni?",answer:"Wizyt\xF3wka do 3 podstron kosztuje 2 900-3 900 z\u0142 netto, wersja z indywidualnym projektem i sze\u015Bcioma podstronami 4 900-6 500 z\u0142, a strona z blogiem i systemem zarz\u0105dzania tre\u015Bci\u0105 7 000-11 000 z\u0142. Do tego dochodzi hosting od 80 z\u0142 miesi\u0119cznie i opcjonalna opieka techniczna od 250 z\u0142 miesi\u0119cznie. Rezerwacja wizyt to osobna pozycja: od 1 800 z\u0142 za osadzenie gotowego systemu."},{question:"Ile trwa wykonanie strony dla plac\xF3wki medycznej?",answer:"Wizyt\xF3wka Basic 1-2 tygodnie, Custom 2-4 tygodnie, strona z blogiem i CMS 3-6 tygodni - licz\u0105c od otrzymania kompletu materia\u0142\xF3w i zaliczki. Termin przesuwa si\u0119 najcz\u0119\u015Bciej z powodu materia\u0142\xF3w po stronie plac\xF3wki: zdj\u0119\u0107 zespo\u0142u, zatwierdzonego cennika i opis\xF3w us\u0142ug wymagaj\u0105cych akceptacji merytorycznej."},{question:"Czy strona b\u0119dzie zgodna z RODO?",answer:"Formularze zbieraj\u0105 tylko dane potrzebne do odpowiedzi, zawieraj\u0105 klauzul\u0119 informacyjn\u0105 i osobn\u0105 zgod\u0119 na kontakt, a dane trafiaj\u0105 na serwer w Unii Europejskiej. Plac\xF3wka dostaje te\u017C polityk\u0119 prywatno\u015Bci dopasowan\u0105 do tego, co strona faktycznie zbiera, a nie szablon z internetu."},{question:"Czy mog\u0119 sam edytowa\u0107 tre\u015Bci?",answer:"Tak. Cennik, godziny przyj\u0119\u0107, sk\u0142ad zespo\u0142u i aktualno\u015Bci edytuje si\u0119 z panelu bez znajomo\u015Bci kodu. Zmiany w strukturze strony i nowe podstrony us\u0142ug robimy w ramach opieki albo na zlecenie."}],related:[{path:"/uslugi/pozycjonowanie-klinik",label:"Pozycjonowanie klinik",description:"Strona bez widoczno\u015Bci w Google nie pozyskuje pacjent\xF3w."},{path:"/wiedza/ile-kosztuje-strona-dla-przychodni",label:"Ile kosztuje strona internetowa dla przychodni",description:"Z czego sk\u0142ada si\u0119 wycena i gdzie firmy ukrywaj\u0105 koszty."}]},{slug:"social-media-dla-klinik",navLabel:"Social media",h1:"Social media dla klinik, gabinet\xF3w i lekarzy",seoTitle:"Social media dla klinik, gabinet\xF3w i lekarzy | mediaso",seoDescription:"Prowadzimy Facebooka i Instagrama klinik, gabinet\xF3w i lekarzy: tre\u015Bci, grafiki, wideo, obs\u0142uga wiadomo\u015Bci. Od 2 700 z\u0142 miesi\u0119cznie, kampanie Meta Ads wyceniane osobno.",schemaName:"Prowadzenie social media plac\xF3wek medycznych",schemaServiceType:"Zarz\u0105dzanie mediami spo\u0142eczno\u015Bciowymi",priceFrom:"2700",pricing:[{title:"Pakiety prowadzenia social medi\xF3w",rows:[{name:"Pakiet 1",price:"2 999 z\u0142 pierwszy miesi\u0105c",priceNext:"2 700 z\u0142 ka\u017Cdy kolejny miesi\u0105c",features:["audyt i optymalizacja obecnych profili (lub ich za\u0142o\u017Cenie), w tym wizyt\xF3wki Google","strategia komunikacji","12 post\xF3w graficznych i karuzel edukacyjnych miesi\u0119cznie","relacje (Stories) na Instagramie i Facebooku","moderacja komentarzy","miesi\u0119czny harmonogram tre\u015Bci i copywriting","grafiki zgodne z identyfikacj\u0105 wizualn\u0105 plac\xF3wki","10 zdj\u0119\u0107 do wykorzystania w social mediach, na stronie i w wizyt\xF3wce Google"]},{name:"Pakiet 2",price:"3 999 z\u0142 pierwszy miesi\u0105c",priceNext:"3 600 z\u0142 ka\u017Cdy kolejny miesi\u0105c",features:["audyt i optymalizacja obecnych profili (lub ich za\u0142o\u017Cenie), w tym wizyt\xF3wki Google","strategia komunikacji","8 post\xF3w graficznych lub karuzel i 4 rolki na Instagram i Facebook","TikTok: 4 filmy miesi\u0119cznie","raz w miesi\u0105cu sesja nagraniowo-zdj\u0119ciowa w plac\xF3wce","miesi\u0119czny harmonogram tre\u015Bci i copywriting","relacje (Stories) na Instagramie i Facebooku","dedykowana oprawa graficzna","moderacja komentarzy","20 zdj\u0119\u0107 do wykorzystania w social mediach, na stronie i w wizyt\xF3wce Google"]},{name:"Pakiet 3",price:"4 499 z\u0142 pierwszy miesi\u0105c",priceNext:"3 900 z\u0142 ka\u017Cdy kolejny miesi\u0105c",features:["audyt i optymalizacja obecnych profili (lub ich za\u0142o\u017Cenie), w tym wizyt\xF3wki Google","strategia komunikacji","8 post\xF3w graficznych lub karuzel i 6 rolek na Instagram i Facebook","TikTok: 6 film\xF3w miesi\u0119cznie","raz w miesi\u0105cu sesja nagraniowo-zdj\u0119ciowa w plac\xF3wce","miesi\u0119czny harmonogram tre\u015Bci i copywriting","relacje (Stories) na Instagramie i Facebooku","dedykowana oprawa graficzna","moderacja komentarzy","20 zdj\u0119\u0107 do wykorzystania w social mediach, na stronie i w wizyt\xF3wce Google"]}]}],lead:"Profil kliniki na Facebooku i Instagramie pe\u0142ni rol\u0119, o kt\xF3rej \u0142atwo zapomnie\u0107: pacjent, kt\xF3ry us\u0142ysza\u0142 nazw\u0119 plac\xF3wki od znajomego, sprawdza j\u0105 tam, zanim zadzwoni. Widzi wtedy albo pracuj\u0105c\u0105 plac\xF3wk\u0119 z aktualnymi informacjami i odpowiedziami na wiadomo\u015Bci, albo profil z ostatnim postem sprzed roku. To rozstrzyga wi\u0119cej decyzji ni\u017C jakakolwiek kampania. Prowadzenie social medi\xF3w plac\xF3wki medycznej sprowadza si\u0119 wi\u0119c najpierw do regularno\u015Bci i obs\u0142ugi wiadomo\u015Bci, a dopiero potem do zasi\u0119g\xF3w. Dochodzi do tego ograniczenie, kt\xF3rego nie ma w innych bran\u017Cach: nie wolno publikowa\u0107 wizerunku ani danych pacjenta bez zgody, a tre\u015B\u0107 nie mo\u017Ce obiecywa\u0107 efektu leczenia. Pracujemy w rytmie miesi\u0119cznym, na planie tre\u015Bci zatwierdzanym z wyprzedzeniem.",sections:[{heading:"Co publikujemy zamiast cytat\xF3w o zdrowiu",paragraphs:["Tre\u015Bci, kt\xF3re w plac\xF3wkach medycznych realnie generuj\u0105 kontakt, s\u0105 konkretne: nowy sprz\u0119t i co dzi\u0119ki niemu mo\u017Cna zbada\u0107, nowy specjalista z zakresem przyj\u0119\u0107, wolne terminy w tym tygodniu, przygotowanie do konkretnego badania, odpowied\u017A na pytanie, kt\xF3re rejestracja s\u0142yszy codziennie.","Post z og\xF3ln\u0105 grafik\u0105 o dbaniu o zdrowie nie przynosi nic poza wype\u0142nieniem kalendarza. Plan tre\u015Bci uk\u0142adamy z zespo\u0142em plac\xF3wki, bo to rejestracja i lekarze wiedz\u0105, o co pacjenci pytaj\u0105 najcz\u0119\u015Bciej."],bullets:["zapowiedzi wolnych termin\xF3w i nowych us\u0142ug","przedstawienie specjalist\xF3w: zakres przyj\u0119\u0107, do\u015Bwiadczenie, j\u0119zyki","instrukcje przygotowania do bada\u0144 w formie kr\xF3tkiego wideo","odpowiedzi na powtarzalne pytania z rejestracji","komunikaty organizacyjne: dni wolne, zmiany godzin, nowy adres"]},{heading:"Profil lekarza a profil plac\xF3wki",paragraphs:["Lekarz prowadz\u0105cy w\u0142asn\u0105 praktyk\u0119 potrzebuje czego\u015B innego ni\u017C przychodnia z sze\u015Bcioma poradniami. Profil plac\xF3wki komunikuje dost\u0119pno\u015B\u0107, zakres us\u0142ug i organizacj\u0119. Profil lekarza sprzedaje kompetencj\u0119 konkretnej osoby, wi\u0119c tre\u015B\u0107 stoi na tym, co ten specjalista realnie robi: jakie przypadki prowadzi, na jakim sprz\u0119cie pracuje, na jakich konferencjach bywa i co z tego wynika dla pacjenta.","Prowadzimy oba warianty, a przy lekarzu zatrudnionym w kilku miejscach ustalamy na starcie, co nale\u017Cy do jego marki osobistej, a co do marki plac\xF3wki. Bez tego rozdzia\u0142u pojawia si\u0119 problem przy zmianie pracy: profil zbudowany wok\xF3\u0142 adresu przychodni traci sens, gdy lekarz zaczyna przyjmowa\u0107 gdzie indziej.","Jedno ograniczenie dotyczy obu przypadk\xF3w tak samo. Lekarz wyst\u0119puj\u0105cy we w\u0142asnym imieniu podlega zasadom kodeksu etyki lekarskiej co do tre\u015Bci reklamowych, wi\u0119c materia\u0142 opiera si\u0119 na informacji o zakresie przyj\u0119\u0107 i przebiegu leczenia, nie na obietnicy wyniku."],bullets:["profil lekarza: marka osobista, zakres przyj\u0119\u0107, do\u015Bwiadczenie, wyst\u0105pienia","profil plac\xF3wki: dost\u0119pno\u015B\u0107 termin\xF3w, organizacja, zesp\xF3\u0142, us\u0142ugi","rozdzia\u0142 tre\u015Bci przy lekarzu przyjmuj\u0105cym w kilku miejscach","wideo z lekarzem jako materia\u0142, kt\xF3rego nie skopiuje \u017Cadna konkurencja"]},{heading:"Obs\u0142uga wiadomo\u015Bci i komentarzy",paragraphs:["Wiadomo\u015Bci na Messengerze i Instagramie to dzi\u015B ta sama kolejka co telefon do rejestracji, tylko bez sygna\u0142u zaj\u0119to\u015Bci. Ustalamy z plac\xF3wk\u0105, na co odpowiadamy sami, a co przekazujemy do rejestracji - i w jakim czasie.","Twarda zasada: \u017Cadnych porad medycznych i \u017Cadnych danych o stanie zdrowia w wiadomo\u015Bciach. Pytania o objawy przekierowujemy do kontaktu telefonicznego lub wizyty. Komentarze z negatywn\u0105 opini\u0105 zostaj\u0105 widoczne, odpowied\u017A idzie publicznie i bez ujawniania, czy autor by\u0142 pacjentem, bo samo potwierdzenie tego faktu jest ujawnieniem danych o zdrowiu."]},{heading:"Kampanie Meta Ads dla plac\xF3wki",paragraphs:["Reklamy uruchamiamy pod konkretny cel: zape\u0142nienie grafiku nowej poradni, promocj\u0119 us\u0142ugi komercyjnej albo pozyskanie kontakt\xF3w na konsultacj\u0119. Kampania bez celu liczbowego ko\u0144czy si\u0119 raportem z zasi\u0119gami, kt\xF3rych nie da si\u0119 prze\u0142o\u017Cy\u0107 na przych\xF3d.","Meta ma osobne ograniczenia dla reklam dotycz\u0105cych zdrowia - nie pozwala mi\u0119dzy innymi kierowa\u0107 przekazu na domniemany stan zdrowia odbiorcy. Piszemy wi\u0119c teksty m\xF3wi\u0105ce o us\u0142udze i plac\xF3wce, nie o problemie odbiorcy, i to samo dotyczy kierowania kampanii.","Kampanie nie wchodz\u0105 w \u017Caden pakiet prowadzenia profili - wyceniamy je osobno, zale\u017Cnie od celu i liczby kampanii. Bud\u017Cet mediowy, czyli kwota wydana na same reklamy w Meta, jest osobnym kosztem."],bullets:["cel kampanii wyra\u017Cony liczb\u0105 kontakt\xF3w lub wizyt, nie zasi\u0119giem","osobne kampanie dla us\u0142ug komercyjnych i dla informacji organizacyjnych","pomiar telefon\xF3w i formularzy, nie tylko klikni\u0119\u0107","raport miesi\u0119czny z kosztem pozyskania kontaktu"]},{heading:"Jak wygl\u0105da wsp\xF3\u0142praca",paragraphs:["Zaczynamy od audytu profili i przegl\u0105du tego, co plac\xF3wka publikowa\u0142a do tej pory. Potem ustalamy plan tre\u015Bci na miesi\u0105c, zbieramy materia\u0142 zdj\u0119ciowy i wideo na miejscu albo pracujemy na materia\u0142ach plac\xF3wki, a publikacj\u0119 poprzedza akceptacja.","Pracujemy w trzech pakietach, od 2 999 z\u0142otych za pierwszy miesi\u0105c i 2 700 z\u0142otych za ka\u017Cdy kolejny. Pierwszy miesi\u0105c kosztuje wi\u0119cej, bo obejmuje audyt i optymalizacj\u0119 profili albo ich za\u0142o\u017Cenie, razem z wizyt\xF3wk\u0105 Google. Pakiety 2 i 3 dok\u0142adaj\u0105 rolki, filmy na TikToku i comiesi\u0119czn\u0105 sesj\u0119 nagraniowo-zdj\u0119ciow\u0105 w plac\xF3wce. Pe\u0142ny zakres pakiet\xF3w jest w cenniku na dole strony."]}],faq:[{question:"Czy klinika mo\u017Ce pokazywa\u0107 pacjent\xF3w w social mediach?",answer:"Tylko za pisemn\u0105 zgod\u0105 na publikacj\u0119 wizerunku, ze wskazaniem kana\u0142u i mo\u017Cliwo\u015Bci\u0105 wycofania. Samo pokazanie osoby w plac\xF3wce medycznej ujawnia informacj\u0119 o korzystaniu ze \u015Bwiadcze\u0144, czyli dane szczeg\xF3lnej kategorii. Bez zgody publikujemy wy\u0142\u0105cznie materia\u0142y z zespo\u0142em i wn\u0119trzami bez pacjent\xF3w."},{question:"Czy prowadzicie social media dla pojedynczego lekarza, nie dla ca\u0142ej plac\xF3wki?",answer:"Tak. Profil lekarza prowadzimy jako mark\u0119 osobist\u0105: zakres przyj\u0119\u0107, prowadzone przypadki, sprz\u0119t, wyst\u0105pienia i publikacje. To inna praca ni\u017C profil przychodni, kt\xF3ra komunikuje g\u0142\xF3wnie dost\u0119pno\u015B\u0107 i organizacj\u0119. Przy lekarzu przyjmuj\u0105cym w kilku miejscach ustalamy na starcie, kt\xF3re tre\u015Bci nale\u017C\u0105 do jego marki, a kt\xF3re do marki plac\xF3wki."},{question:"Ile post\xF3w miesi\u0119cznie ma sens dla plac\xF3wki medycznej?",answer:"Cztery publikacje tygodniowo utrzymuj\u0105 profil w rotacji i daj\u0105 zapas tre\u015Bci na wiadomo\u015Bci i relacje. Poni\u017Cej dw\xF3ch tygodniowo profil wygl\u0105da na porzucony. Powy\u017Cej o\u015Bmiu ro\u015Bnie koszt, a przyrost kontakt\xF3w zwykle ju\u017C nie nad\u0105\u017Ca."},{question:"Kto odpowiada na wiadomo\u015Bci od pacjent\xF3w?",answer:"Ustalamy podzia\u0142 na starcie. Pytania organizacyjne - godziny, ceny, zakres us\u0142ug - obs\u0142ugujemy my. Wszystko, co dotyczy stanu zdrowia, terminu wizyty konkretnego pacjenta lub wynik\xF3w, idzie do rejestracji plac\xF3wki. Nigdy nie udzielamy porad medycznych w imieniu plac\xF3wki."},{question:"Czy prowadzicie profile na TikToku i YouTubie?",answer:"Prowadzimy, je\u015Bli plac\xF3wka ma specjalist\u0119 gotowego regularnie wyst\u0119powa\u0107 przed kamer\u0105. Bez tego kana\u0142y wideo nie maj\u0105 z czego \u017Cy\u0107 i lepiej zainwestowa\u0107 ten bud\u017Cet w Google i wizyt\xF3wk\u0119."}],related:[{path:"/uslugi/wizytowka-google-dla-placowki",label:"Wizyt\xF3wka Google dla plac\xF3wki",description:"Pacjent sprawdza mapy i opinie, zanim otworzy Facebooka."},{path:"/wiedza/rodo-w-marketingu-placowki-medycznej",label:"RODO w marketingu plac\xF3wki medycznej",description:"Zgody na wizerunek, opinie i kontakt - co trzeba mie\u0107 na pi\u015Bmie."}]},{slug:"wizytowka-google-dla-placowki",navLabel:"Wizyt\xF3wka Google",h1:"Wizyt\xF3wka Google dla plac\xF3wki medycznej",seoTitle:"Optymalizacja wizyt\xF3wki Google dla plac\xF3wki medycznej | mediaso",seoDescription:"Prowadzimy Profil Firmy w Google dla klinik i przychodni: kategorie, us\u0142ugi, zdj\u0119cia, opinie pacjent\xF3w, posty i raport widoczno\u015Bci w mapach.",schemaName:"Optymalizacja Profilu Firmy w Google",schemaServiceType:"Local SEO",pricing:[{title:"Wdro\u017Cenie",rows:[{name:"Audyt i wdro\u017Cenie profilu",price:"900 \u2013 1 400 z\u0142 jednorazowo",scope:"audyt wizyt\xF3wki z list\u0105 priorytet\xF3w i pe\u0142na optymalizacja: kategorie, us\u0142ugi, atrybuty, zdj\u0119cia"}]},{title:"Bie\u017C\u0105ca obs\u0142uga",rows:[{name:"Pakiet Start",price:"600 \u2013 900 z\u0142/mies.",scope:"aktualne godziny i us\u0142ugi, zdj\u0119cia, posty, odpowiedzi na opinie"},{name:"Pakiet Optymalny",price:"900 \u2013 1 500 z\u0142/mies.",scope:"zakres Start oraz systemowe zbieranie opinii, frazy lokalne i comiesi\u0119czny raport widoczno\u015Bci"},{name:"Plac\xF3wka z kilkoma lokalizacjami",price:"wycena indywidualna",scope:"osobna wizyt\xF3wka dla ka\u017Cdego oddzia\u0142u, jedna umowa i jeden zbiorczy raport"}]}],lead:"Wizyt\xF3wka Google jest dla plac\xF3wki medycznej wa\u017Cniejsza ni\u017C strona internetowa, bo pacjent widzi j\u0105 pierwsz\u0105 i cz\u0119sto na niej ko\u0144czy. Z panelu w mapach dzwoni, sprawdza godziny, czyta opinie i wyznacza tras\u0119 - bez otwierania witryny. Trzy rzeczy decyduj\u0105 o tym, czy plac\xF3wka pojawia si\u0119 w lokalnych wynikach: poprawnie dobrana kategoria g\u0142\xF3wna, kompletno\u015B\u0107 profilu oraz opinie, ich liczba, \u015Bwie\u017Co\u015B\u0107 i odpowiedzi plac\xF3wki. Wi\u0119kszo\u015B\u0107 wizyt\xF3wek przychodni przegrywa na pierwszym punkcie, bo ma ustawion\u0105 kategori\u0119 og\xF3ln\u0105 zamiast tej, kt\xF3rej realnie szuka pacjent. Prowadzimy profil jak sta\u0142\u0105 pozycj\u0119: uzupe\u0142niamy us\u0142ugi i godziny, publikujemy zdj\u0119cia i posty, pilnujemy sp\xF3jno\u015Bci danych z innymi serwisami i odpowiadamy na opinie w spos\xF3b, kt\xF3ry nie ujawnia, kto by\u0142 pacjentem.",sections:[{heading:"Kategoria i us\u0142ugi - miejsce, gdzie przegrywa wi\u0119kszo\u015B\u0107 plac\xF3wek",paragraphs:['Kategoria g\u0142\xF3wna to najmocniejszy sygna\u0142 w lokalnych wynikach. Przychodnia z kategori\u0105 \u201Eprzychodnia" nie pojawi si\u0119 na zapytanie o ortodont\u0119, nawet je\u015Bli ortodonta przyjmuje na miejscu. Dobieramy kategori\u0119 g\u0142\xF3wn\u0105 pod us\u0142ug\u0119 o najwi\u0119kszej warto\u015Bci i uzupe\u0142niamy list\u0119 kategorii dodatkowych.',"Do tego wype\u0142niamy sekcj\u0119 us\u0142ug konkretnymi nazwami zabieg\xF3w i bada\u0144 z kr\xF3tkimi opisami. Ta lista pojawia si\u0119 w profilu i pomaga Google zrozumie\u0107, na jakie zapytania wy\u015Bwietla\u0107 plac\xF3wk\u0119."],bullets:["dob\xF3r kategorii g\u0142\xF3wnej pod us\u0142ug\u0119 o najwy\u017Cszej warto\u015Bci","kategorie dodatkowe pokrywaj\u0105ce reszt\u0119 zakresu przyj\u0119\u0107","lista us\u0142ug z opisami i cenami, je\u015Bli plac\xF3wka je publikuje","atrybuty: dost\u0119pno\u015B\u0107 dla w\xF3zk\xF3w, parking, p\u0142atno\u015Bci, teleporady"]},{heading:"Godziny, zdj\u0119cia i posty",paragraphs:["Godziny musz\u0105 by\u0107 zgodne z rzeczywisto\u015Bci\u0105, \u0142\u0105cznie z dniami \u015Bwi\u0105tecznymi i przerwami urlopowymi. Pacjent, kt\xF3ry przyjdzie pod zamkni\u0119te drzwi w godzinach podanych w mapach, zostawia opini\u0119 i to ta opinia zostaje na lata.","Zdj\u0119cia aktualizujemy cyklicznie: wej\u015Bcie od strony ulicy, poczekalnia, gabinety, zesp\xF3\u0142, sprz\u0119t. Wej\u015Bcie od ulicy jest wa\u017Cniejsze, ni\u017C si\u0119 wydaje - po nim pacjent rozpoznaje budynek. Posty publikujemy z informacjami o wolnych terminach, nowych specjalistach i zmianach organizacyjnych."]},{heading:"Opinie: zbieranie i odpowiadanie",paragraphs:["Pro\u015Bb\u0119 o opini\u0119 wysy\u0142amy do wszystkich pacjent\xF3w z danej grupy, nie tylko do tych, kt\xF3rzy wygl\u0105daj\u0105 na zadowolonych, i nie oferujemy niczego w zamian. Selekcja i wynagradzanie \u0142ami\u0105 zasady Google i wywracaj\u0105 wiarygodno\u015B\u0107 profilu, gdy wyjd\u0105 na jaw.","Odpowiadamy na ka\u017Cd\u0105 opini\u0119, tak\u017Ce negatywn\u0105, i nigdy nie potwierdzamy w odpowiedzi, \u017Ce autor by\u0142 pacjentem plac\xF3wki. Standardowa formu\u0142a: podzi\u0119kowanie, zaproszenie do kontaktu bezpo\u015Bredniego, \u017Cadnych szczeg\xF3\u0142\xF3w o leczeniu. Wyja\u015Bnienia id\u0105 w rozmowie, nie publicznie."],bullets:["pro\u015Bba o opini\u0119 po wizycie, wysy\u0142ana systemowo do ca\u0142ej grupy pacjent\xF3w","odpowied\u017A na ka\u017Cd\u0105 opini\u0119 w ci\u0105gu kilku dni roboczych","zg\u0142aszanie opinii \u0142ami\u0105cych zasady platformy zamiast wdawania si\u0119 w sp\xF3r","monitoring \u015Bredniej oceny i tempa przyrostu opinii"]},{heading:"Plac\xF3wki z kilkoma adresami",paragraphs:["Ka\u017Cdy oddzia\u0142 to osobna wizyt\xF3wka pod w\u0142asnym adresem i numerem telefonu, spi\u0119ta z podstron\u0105 tego oddzia\u0142u na stronie. Wsp\xF3lna wizyt\xF3wka dla trzech lokalizacji nie wy\u015Bwietli si\u0119 w \u017Cadnej z nich poprawnie.","Przy wi\u0119kszej liczbie oddzia\u0142\xF3w pilnujemy sp\xF3jno\u015Bci nazw i danych mi\u0119dzy wizyt\xF3wkami, katalogami bran\u017Cowymi i stron\u0105. Rozjazd w numerze telefonu albo w nazwie os\u0142abia lokalne wyniki wszystkich lokalizacji naraz."]}],faq:[{question:"Czy plac\xF3wka medyczna mo\u017Ce mie\u0107 wizyt\xF3wk\u0119 Google bez podawania adresu?",answer:"Plac\xF3wka przyjmuj\u0105ca pacjent\xF3w w gabinecie musi poda\u0107 adres - to warunek pojawienia si\u0119 w mapach. Ukrycie adresu jest przewidziane dla firm doje\u017Cd\u017Caj\u0105cych do klienta i przy stacjonarnej przychodni zadzia\u0142a przeciwko widoczno\u015Bci."},{question:"Jak szybko wida\u0107 efekty optymalizacji wizyt\xF3wki?",answer:"Zmiany kategorii i uzupe\u0142nienie profilu Google przetwarza zwykle w kilka dni, a pierwsze r\xF3\u017Cnice w liczbie wy\u015Bwietle\u0144 i telefon\xF3w wida\u0107 w statystykach profilu po dw\xF3ch do czterech tygodniach. Wzrost nap\u0119dzany opiniami jest wolniejszy, bo zale\u017Cy od tempa ich zbierania."},{question:"Co zrobi\u0107 z fa\u0142szyw\u0105 negatywn\u0105 opini\u0105?",answer:"Zg\u0142osi\u0107 j\u0105 do Google jako naruszenie zasad i r\xF3wnolegle odpowiedzie\u0107 publicznie w spos\xF3b rzeczowy, bez ujawniania, czy autor by\u0142 pacjentem. Google usuwa cz\u0119\u015B\u0107 zg\u0142osze\u0144, ale nie wszystkie - spokojna odpowied\u017A pod opini\u0105 pracuje na wizerunek nawet wtedy, gdy opinia zostaje."},{question:"Czy warto p\u0142aci\u0107 za pozycjonowanie wizyt\xF3wki?",answer:"Warto, je\u015Bli praca polega na uzupe\u0142nianiu profilu, zbieraniu opinii i publikowaniu tre\u015Bci. Nie warto, je\u015Bli wykonawca obiecuje sztuczne opinie albo manipulacj\u0119 lokalizacj\u0105 - Google karze za to zawieszeniem profilu, a odzyskanie go bywa trudne."}],related:[{path:"/uslugi/pozycjonowanie-klinik",label:"Pozycjonowanie klinik",description:"Wizyt\xF3wka i strona pracuj\u0105 razem albo \u017Cadna nie wychodzi wysoko."},{path:"/uslugi/social-media-dla-klinik",label:"Social media dla klinik",description:"Drugie miejsce, w kt\xF3rym pacjent sprawdza plac\xF3wk\u0119 przed telefonem."},{path:"/wiedza/jak-zbierac-opinie-pacjentow",label:"Jak zbiera\u0107 opinie pacjent\xF3w zgodnie z prawem",description:"Gotowa procedura zbierania opinii bez selekcji i nagr\xF3d."}]}];var z="/uslugi",n="/wiedza",r=a=>`${z}/${a}`,t=a=>`${n}/${a}`,p=a=>o.find(i=>i.slug===a),d=a=>e.find(i=>i.slug===a),k=["/","/uslugi","/o-nas","/kontakt","/diagnostyka",n,...o.map(a=>r(a.slug)),...e.map(a=>t(a.slug))];export{e as a,o as b,r as c,t as d,p as e,d as f};
